import { useEffect, useMemo, useRef, useState } from 'react';
import { deleteEntity, loadDatabase, saveEntity } from './db/database';

const icon = (symbol) => <span className="nav-icon" aria-hidden="true">{symbol}</span>;
const navigation = [
  ['overview', 'Обзор', '⌂'], ['tasks', 'Задачи', '✓'], ['directories', 'Справочники', '▦'],
  ['documents', 'Документы', '▤'], ['reports', 'Отчёты', '▥'], ['settings', 'Настройки', '⚙'], ['chat', 'Чат', '✦'],
];
const roleLevels = { 'Наблюдатель': 0, 'Исполнитель': 1, 'Постановщик': 2, 'Руководитель': 3, 'Администратор': 4, 'Руководитель проекта': 3, 'Специалист': 1 };
const canManageTask = (user, task) => (roleLevels[user?.role] ?? 0) >= 3 || task.ownerId === user?.id;
const canCreateTask = (user) => (roleLevels[user?.role] ?? 0) >= 1;
const generatePassword = () => { const letters = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'; const digits = '23456789'; let value = letters[Math.floor(Math.random() * letters.length)] + digits[Math.floor(Math.random() * digits.length)]; for (let index = 0; index < 8; index += 1) { const characters = letters + digits; value += characters[Math.floor(Math.random() * characters.length)]; } return value.split('').sort(() => Math.random() - .5).join(''); };
const loginFromName = (name) => { const letters = { а: 'a', б: 'b', в: 'v', г: 'g', д: 'd', е: 'e', ё: 'e', ж: 'zh', з: 'z', и: 'i', й: 'y', к: 'k', л: 'l', м: 'm', н: 'n', о: 'o', п: 'p', р: 'r', с: 's', т: 't', у: 'u', ф: 'f', х: 'h', ц: 'ts', ч: 'ch', ш: 'sh', щ: 'sch', ы: 'y', э: 'e', ю: 'yu', я: 'ya', ь: '', ъ: '' }; return (name.trim().split(/\s+/)[0] ?? '').toLowerCase().split('').map((letter) => letters[letter] ?? letter).join('').replace(/[^a-z0-9]/g, ''); };

const statusClass = (status) => ({ 'В работе': 'blue', 'Утверждение': 'amber', 'Завершено': 'green', 'Просрочено': 'red' }[status] ?? 'gray');
const priorityClass = (priority) => ({ 'Высокий': 'red', 'Обычный': 'amber' }[priority] ?? 'gray');
const dateText = (date) => new Intl.DateTimeFormat('ru-RU', { day: '2-digit', month: '2-digit', year: 'numeric' }).format(new Date(`${date}T00:00:00`));
const dueText = (task) => `${dateText(task.dueDate)} ${task.dueTime ?? '18:00'}`;
const taskNumberPrefix = () => new Date().toISOString().slice(0, 10).replaceAll('-', '');
const nextTaskNumber = (tasks) => {
  const prefix = `${taskNumberPrefix()}-`;
  const sequence = tasks.reduce((maximum, task) => task.number?.startsWith(prefix) ? Math.max(maximum, Number(task.number.slice(prefix.length)) || 0) : maximum, 0);
  return `${prefix}${String(sequence + 1).padStart(3, '0')}`;
};
const progressPercent = (task) => {
  const performers = task.performerIds ?? [];
  if (!performers.length) return 0;
  const completed = new Set(task.completedPerformerIds ?? []);
  return Math.round((performers.filter((performerId) => completed.has(performerId)).length / performers.length) * 100);
};
const taskAssignmentMessages = (task, previousPerformerIds = []) => {
  const previous = new Set(previousPerformerIds);
  const createdAt = new Date().toISOString();
  return [...new Set(task.performerIds ?? [])]
    .filter((performerId) => performerId !== task.ownerId && !previous.has(performerId))
    .map((recipientId, index) => ({ id: `task-assignment-${task.id}-${Date.now()}-${index}`, senderId: task.ownerId, recipientId, text: `Вам назначена задача № ${task.number}: «${task.title}».`, createdAt, type: 'task-assignment', taskId: task.id }));
};
const escapeExportValue = (value) => String(value ?? '—').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const downloadExport = (content, filename, type) => { const link = document.createElement('a'); const url = URL.createObjectURL(new Blob([`\ufeff${content}`], { type })); link.href = url; link.download = filename; link.click(); URL.revokeObjectURL(url); };

function Avatar({ user, small = false }) {
  return <span className={`avatar ${small ? 'avatar-small' : ''}`} style={{ background: user?.color ?? '#506782' }}>{user?.initials ?? '—'}</span>;
}

function BrandMark() {
  return <div className="brand-mark" aria-label="Вектор">
    <svg className="brand-symbol" viewBox="0 0 32 32" aria-hidden="true">
      <path d="M7 24 15 16l7-7M17 9h5v5" />
      <circle cx="7" cy="24" r="3.5" />
      <circle cx="15" cy="16" r="3.5" />
      <circle cx="22" cy="9" r="3.5" />
    </svg>
    <span>Вектор</span>
  </div>;
}

function Login({ users, onLogin }) {
  const [login, setLogin] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const submit = (event) => { event.preventDefault(); const matchedUser = users.find((candidate) => candidate.login?.toLowerCase() === login.trim().toLowerCase() && candidate.password === password); if (!matchedUser) { setError('Неверный логин или пароль.'); return; } setError(''); onLogin(matchedUser); };
  return <main className="login-page"><section className="login-panel"><BrandMark/><div><h1>Рабочее пространство организации</h1><p>Управляйте задачами, справочниками и нормативной документацией в единой системе.</p></div><form className="login-form" onSubmit={submit}><label>Логин<input value={login} onChange={(event) => setLogin(event.target.value)} autoComplete="username" aria-label="Логин" required/></label><label>Пароль<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} autoComplete="current-password" aria-label="Пароль" required/></label>{error ? <p className="login-error" role="alert">{error}</p> : null}<button className="primary-button wide" type="submit">Войти в систему <span>→</span></button></form><small>Тестовый вход: <b>admin</b> / <b>admin123</b>. Это локальная демонстрация без серверной защиты.</small></section><aside className="login-art"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="login-preview"><div className="preview-head"><span>Вектор</span><i/></div><div className="preview-line short"/><div className="preview-line"/><div className="preview-list"><b/><b/><b/></div></div><p>Единое пространство для управляемой работы</p></aside></main>;
}

function Sidebar({ section, setSection, user }) {
  const [settingsOpen, setSettingsOpen] = useState(true);
  const [documentsOpen, setDocumentsOpen] = useState(true);
  return <aside className="sidebar"><BrandMark/><nav>{navigation.map(([key, label, glyph]) => key === 'settings' ? <div className="settings-nav" key={key}><button className={section.startsWith('settings') ? 'nav-item active' : 'nav-item'} onClick={() => setSettingsOpen((open) => !open)}>{icon(glyph)}<span>{label}</span><b>{settingsOpen ? '⌃' : '⌄'}</b></button>{settingsOpen ? <div className="settings-submenu"><button className={section === 'settings-organization' ? 'active' : ''} onClick={() => setSection('settings-organization')}>Организация</button><button className={section === 'settings-directories' ? 'active' : ''} onClick={() => setSection('settings-directories')}>Настройка справочников</button><button className={section === 'settings-users' ? 'active' : ''} onClick={() => setSection('settings-users')}>Пользователи</button></div> : null}</div> : key === 'documents' ? <div className="settings-nav" key={key}><button className={section.startsWith('documents') ? 'nav-item active' : 'nav-item'} onClick={() => { setDocumentsOpen((open) => !open); if (!section.startsWith('documents')) setSection('documents-normative'); }}>{icon(glyph)}<span>{label}</span><b>{documentsOpen ? '⌃' : '⌄'}</b></button>{documentsOpen ? <div className="settings-submenu"><button className={section === 'documents-normative' ? 'active' : ''} onClick={() => setSection('documents-normative')}>Нормативные документы</button><button className={section === 'documents-internal' ? 'active' : ''} onClick={() => setSection('documents-internal')}>Внутренние документы</button></div> : null}</div> : <button key={key} className={section === key ? 'nav-item active' : 'nav-item'} onClick={() => setSection(key)}>{icon(glyph)}<span>{label}</span></button>)}</nav><div className="sidebar-bottom"><div className="sidebar-user"><Avatar user={user}/><div><strong>{user.name}</strong><small>{user.role}</small></div></div><button className="collapse">‹ <span>Свернуть</span></button></div></aside>;
}

function Topbar({ user, onLogout, search, setSearch }) {
  return <header className="topbar"><label className="global-search"><span>⌕</span><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Поиск по задачам, документам, справочникам..." /></label><div className="top-actions"><button className="icon-button" aria-label="Уведомления">♧<em>3</em></button><Avatar user={user}/><div className="account-name">{user.name}</div><button className="logout" onClick={onLogout}>Выйти</button></div></header>;
}

function TaskTable({ tasks, users, selectedId, onSelect, onEdit }) {
  return <div className="table-wrap"><table><thead><tr><th>Номер</th><th>Название задачи</th><th>Статус</th><th>Приоритет</th><th>Постановщик задачи</th><th>Срок</th></tr></thead><tbody>{tasks.map((task) => { const owner = users.find((user) => user.id === task.ownerId); return <tr key={task.id} className={selectedId === task.id ? 'selected' : ''} onClick={() => onSelect(task.id)} onDoubleClick={() => onEdit(task)}><td>{task.number}</td><td><strong className="task-title">{task.title}</strong></td><td><span className={task.status === 'Просрочено' ? 'status overdue' : 'status'}>{task.status}</span></td><td><span className="status">{task.priority}</span></td><td><span className="owner"><Avatar user={owner} small/>{owner?.name}</span></td><td className={task.status === 'Просрочено' ? 'overdue' : ''}>{dueText(task)}</td></tr>; })}</tbody></table>{!tasks.length && <div className="empty-state">По вашему запросу ничего не найдено.</div>}</div>;
}

function LegacyTaskDetails({ task, users, currentUser, editRequest, onAddPerformer, onAttachFile, onRemoveAttachment, onUpdateTask, onDeleteTask }) {
  const [titleDraft, setTitleDraft] = useState(task?.title ?? '');
  const [newPerformerId, setNewPerformerId] = useState('');
  const [lastSavedTask, setLastSavedTask] = useState(task);
  const [saveMessage, setSaveMessage] = useState('');
  const titleInputRef = useRef(null);
  useEffect(() => { setTitleDraft(task?.title ?? ''); }, [task?.id, task?.title]);
  useEffect(() => { setLastSavedTask(task); setSaveMessage(''); }, [task?.id]);
  useEffect(() => { if (editRequest) titleInputRef.current?.focus(); }, [editRequest]);
  if (!task) return <aside className="details-panel empty-details">Выберите задачу, чтобы посмотреть детали.</aside>;
  const owner = users.find((user) => user.id === task.ownerId);
  const attachments = task.attachments ?? [];
  const ownerAttachments = attachments.filter((attachment) => !attachment.uploadedById || attachment.uploadedById === task.ownerId);
  const performers = users.filter((user) => (task.performerIds ?? []).includes(user.id));
  const canEditTask = canManageTask(currentUser, task);
  const canManageAttachments = canEditTask;
  const isCurrentUserPerformer = (task.performerIds ?? []).includes(currentUser.id);
  const canDownloadAttachments = canManageAttachments || isCurrentUserPerformer;
  const completedPerformerIds = task.completedPerformerIds ?? [];
  const formatSize = (bytes) => bytes < 1024 * 1024 ? `${Math.max(1, Math.round(bytes / 1024))} КБ` : `${(bytes / (1024 * 1024)).toFixed(1)} МБ`;
  const updateField = (field, value) => { if (canEditTask) onUpdateTask(task.id, (current) => ({ ...current, [field]: value })); };
  const toggleCompletion = (performerId, isCompleted) => onUpdateTask(task.id, (current) => { const completedIds = new Set(current.completedPerformerIds ?? []); if (isCompleted) completedIds.add(performerId); else completedIds.delete(performerId); return { ...current, completedPerformerIds: [...completedIds] }; });
  const downloadAttachment = (attachment) => { if (!attachment.blob) return; const url = URL.createObjectURL(attachment.blob); const link = document.createElement('a'); link.href = url; link.download = attachment.name; link.click(); URL.revokeObjectURL(url); };
  return <aside className="details-panel">
    <div className="details-head"><input ref={titleInputRef} className="task-title-input" value={titleDraft} readOnly={!canEditTask} onChange={(event) => setTitleDraft(event.target.value)} onBlur={() => { const title = titleDraft.trim(); if (title !== task.title) updateField('title', title); }} aria-label="Название задачи"/><button className="close-button" disabled={!canEditTask} aria-label="Очистить название задачи" onClick={() => { setTitleDraft(''); updateField('title', ''); }}>×</button></div>
    <section className="task-editor"><label>Статус<select disabled={!canEditTask} value={task.status} onChange={(event) => updateField('status', event.target.value)}><option>В работе</option><option>Утверждение</option><option>Завершено</option><option>Просрочено</option></select></label><label>Приоритет<select disabled={!canEditTask} value={task.priority} onChange={(event) => updateField('priority', event.target.value)}><option>Высокий</option><option>Обычный</option></select></label><label>Срок<div className="deadline-inputs"><input disabled={!canEditTask} type="date" value={task.dueDate} onInput={(event) => updateField('dueDate', event.target.value)} onChange={(event) => updateField('dueDate', event.target.value)}/><input disabled={!canEditTask} type="time" value={task.dueTime ?? '18:00'} onInput={(event) => updateField('dueTime', event.target.value)} onChange={(event) => updateField('dueTime', event.target.value)}/></div></label><label>Постановщик задачи<select disabled={!canEditTask} value={task.ownerId} onChange={(event) => updateField('ownerId', event.target.value)}>{users.map((user) => <option key={user.id} value={user.id}>{user.name}</option>)}</select></label></section>
    <section className="detail-section"><h3>Описание</h3><p>{task.description}</p></section>
    <section className="attachments"><div className="section-line"><h3>Вложения</h3>{canManageAttachments ? <label className="attach-button">＋ Прикрепить файл<input type="file" onChange={(event) => { const [file] = event.target.files; if (file) onAttachFile(task, file); event.target.value = ''; }}/></label> : null}</div>{ownerAttachments.length ? <div className="attachment-list">{ownerAttachments.map((attachment) => { const canRemove = canManageAttachments || attachment.uploadedById === currentUser.id; return <div className="attachment" key={attachment.id}><span className="document-icon">▤</span><div className="attachment-info"><strong>{attachment.name}</strong><small>{attachment.type || 'Файл'} · {formatSize(attachment.size)}</small></div><div className="attachment-actions">{canDownloadAttachments ? <button type="button" onClick={() => downloadAttachment(attachment)}>Скачать</button> : null}{canRemove ? <button type="button" className="remove-attachment" onClick={() => { if (window.confirm(`Удалить вложение «${attachment.name}»?`)) onRemoveAttachment(task, attachment.id); }}>Удалить</button> : null}</div></div>; })}</div> : <p className="muted">Файлы постановщика пока не прикреплены.</p>}{!canDownloadAttachments ? <p className="muted">Вложения доступны постановщику и назначенным исполнителям.</p> : null}</section>
    <section className="performers"><div className="section-line"><h3>Исполнители</h3><span>{performers.length}</span></div>{canManageAttachments ? <div className="performer-controls"><select value={newPerformerId} onChange={(event) => setNewPerformerId(event.target.value)}><option value="">Выберите пользователя</option>{users.filter((user) => !performers.some((performer) => performer.id === user.id)).map((user) => <option key={user.id} value={user.id}>{user.name}</option>)}</select><button disabled={!newPerformerId} onClick={() => { onAddPerformer(task, newPerformerId); setNewPerformerId(''); }}>Добавить</button></div> : <p className="muted">Добавлять исполнителей может постановщик задачи.</p>}{performers.length ? <table className="performers-table"><thead><tr><th>Пользователь</th><th>Исполнение</th><th>Файлы</th></tr></thead><tbody>{performers.map((performer) => { const isCurrentUser = performer.id === currentUser.id; const isCompleted = completedPerformerIds.includes(performer.id); const performerFiles = attachments.filter((attachment) => attachment.uploadedById === performer.id); const canViewPerformerFiles = isCurrentUser || canManageAttachments; return <tr key={performer.id}><td><span className="owner"><Avatar user={performer} small/>{performer.name}</span></td><td>{isCurrentUser ? <label className="completion-check"><input type="checkbox" checked={isCompleted} onChange={(event) => toggleCompletion(performer.id, event.target.checked)}/>Выполнено</label> : <span className={isCompleted ? 'completion-done' : 'completion-pending'}>{isCompleted ? 'Выполнено' : 'В работе'}</span>}</td><td>{canViewPerformerFiles ? <div className="performer-file-actions">{isCurrentUser ? <label className="row-file-button">＋ Файл<input type="file" onChange={(event) => { const [file] = event.target.files; if (file) onAttachFile(task, file); event.target.value = ''; }}/></label> : null}{performerFiles.map((attachment) => <span className="performer-file" key={attachment.id}><button type="button" className="performer-file-download" onClick={() => downloadAttachment(attachment)}>↓ {attachment.name}</button>{isCurrentUser ? <button type="button" aria-label={`Удалить ${attachment.name}`} onClick={() => { if (window.confirm(`Удалить вложение «${attachment.name}»?`)) onRemoveAttachment(task, attachment.id); }}>×</button> : null}</span>)}</div> : null}</td></tr>; })}</tbody></table> : canManageAttachments ? <p className="muted">Добавьте исполнителей из справочника пользователей.</p> : null}</section>
    <section className="detail-section"><div className="section-line"><h3>Прогресс</h3><b>{progressPercent(task)}%</b></div><div className="progress"><span style={{ width: `${progressPercent(task)}%` }}/></div></section>
    <section className="documents-list"><h3>Связанные документы <span>{task.documents.length}</span></h3>{task.documents.map((document) => <button key={document}><span className="document-icon">▤</span><div><strong>{document}</strong><small>Обновлён недавно</small></div></button>) || null}</section>
    <div className="task-actions"><span aria-live="polite">{saveMessage}</span>{canEditTask ? <><button className="save-task" onClick={() => { setLastSavedTask(task); setSaveMessage('Изменения сохранены'); }}>Сохранить</button><button className="cancel-task" onClick={() => { if (lastSavedTask) onUpdateTask(task.id, lastSavedTask); setSaveMessage('Изменения отменены'); }}>Отмена</button><button className="delete-task" onClick={() => { if (window.confirm(`Удалить задачу «${task.title}»?`)) onDeleteTask(task.id); }}>Удалить</button></> : <p className="muted">Редактировать и удалять задачу может только постановщик.</p>}</div>
    <div className="details-footer"><button>▢ Комментарии <em>2</em></button><button>◷ История</button></div>
  </aside>;
}

function TaskDetails({ task, users }) {
  useEffect(() => { if (!task) return; const dynamics = document.querySelector('.task-info-panel .task-status-dynamics'); if (!dynamics) return; const summary = dynamics.nextElementSibling?.classList.contains('task-status-summary') ? dynamics.nextElementSibling : document.createElement('div'); summary.className = 'task-status-summary'; const stats = [['Всего задач', task.taskStats?.total ?? 0, ''], ['В работе', task.taskStats?.working ?? 0, 'blue-text'], ['Просрочено', task.taskStats?.overdue ?? 0, 'red-text'], ['Завершено', task.taskStats?.completed ?? 0, 'green-text']]; summary.replaceChildren(...stats.map(([label, value, className]) => { const item = document.createElement('span'); const title = document.createElement('small'); title.textContent = label; const count = document.createElement('b'); count.textContent = String(value); if (className) count.className = className; item.append(title, count); return item; })); if (!summary.parentNode) dynamics.after(summary); }, [task?.id, task?.taskStats]);
  if (!task) return <aside className="details-panel empty-details">Выберите задачу, чтобы посмотреть информацию.</aside>;
  const owner = users.find((user) => user.id === task.ownerId);
  const performers = users.filter((user) => (task.performerIds ?? []).includes(user.id));
  const completedIds = new Set(task.completedPerformerIds ?? []);
  const progress = progressPercent(task);
  return <aside className="details-panel task-info-panel"><div className="details-head"><h2>{task.title}</h2></div><dl className="detail-list"><div><dt>Вид задачи</dt><dd>{task.kind ?? 'Задача'}</dd></div><div><dt>Номер задачи</dt><dd>{task.number ?? 'Присваивается автоматически'}</dd></div><div><dt>Статус</dt><dd><span className={`status ${task.status === 'Просрочено' ? 'overdue' : ''}`}>{task.status}</span></dd></div><div><dt>Постановщик</dt><dd><span className="owner"><Avatar user={owner} small/>{owner?.name ?? 'Не указан'}</span></dd></div><div><dt>Срок</dt><dd>{dueText(task)}</dd></div></dl><section className="detail-section task-info-performers"><div className="section-line"><h3>Исполнители</h3><b>{performers.length}</b></div>{performers.length ? <div className="task-info-performer-list">{performers.map((performer) => <div key={performer.id}><span className="owner"><Avatar user={performer} small/>{performer.name}</span><label><input type="checkbox" checked={completedIds.has(performer.id)} readOnly/>Выполнено</label></div>)}</div> : <p className="muted">Исполнители не назначены.</p>}</section><section className="detail-section"><div className="section-line"><h3>Прогресс</h3><b>{progress}%</b></div><div className="progress"><span style={{ width: `${progress}%` }}/></div></section><section className="detail-section task-status-dynamics"><h3>Динамика по статусам</h3><svg viewBox="0 0 260 78" role="img" aria-label="Динамика задач по статусам"><path d="M4 62H256M4 38H256M4 14H256" className="chart-grid"/><polyline points="4,48 47,39 90,40 133,30 176,44 219,28 256,30" className="chart-line blue-line"/><polyline points="4,55 47,54 90,56 133,50 176,55 219,49 256,51" className="chart-line amber-line"/><polyline points="4,63 47,63 90,63 133,60 176,63 219,61 256,61" className="chart-line green-line"/></svg><div className="task-status-legend"><span><i className="blue"/>В работе</span><span><i className="amber"/>Просрочено</span><span><i className="green"/>Завершено</span></div></section></aside>;
}

function LegacyTaskEditorScreen({ task, users, documents, currentUser, onSave, onUpdateTask, onCancel }) {
  const emptyTask = { title: '', description: '', status: 'В работе', priority: 'Обычный', ownerId: currentUser.id, dueDate: new Date().toISOString().slice(0, 10), dueTime: '18:00', performerIds: [], documents: [], attachments: [], progress: 0, completedPerformerIds: [] };
  const [draft, setDraft] = useState(() => ({ ...emptyTask, ...task, performerIds: task?.performerIds ?? [], documents: task?.documents ?? [], attachments: task?.attachments ?? [], completedPerformerIds: task?.completedPerformerIds ?? [] }));
  const update = (field, value) => setDraft((current) => ({ ...current, [field]: value }));
  const toggleListItem = (field, value) => setDraft((current) => ({ ...current, [field]: current[field].includes(value) ? current[field].filter((item) => item !== value) : [...current[field], value] }));
  const addFiles = (fileList) => { const files = Array.from(fileList).map((file) => ({ id: `${Date.now()}-${file.name}`, name: file.name, type: file.type, size: file.size, blob: file, uploadedById: currentUser.id })); update('attachments', [...draft.attachments, ...files]); };
  const canEditTask = !task || canManageTask(currentUser, task);
  const canManageAttachments = canEditTask;
  const canDownloadAttachments = canManageAttachments || draft.performerIds.includes(currentUser.id);
  const descriptionAttachments = draft.attachments.filter((attachment) => !attachment.uploadedById || attachment.uploadedById === draft.ownerId);
  const downloadAttachment = (attachment) => { if (!attachment.blob) return; const url = URL.createObjectURL(attachment.blob); const link = document.createElement('a'); link.href = url; link.download = attachment.name; link.click(); URL.revokeObjectURL(url); };
  const addAllPerformers = () => update('performerIds', users.map((user) => user.id));
  const updatePerformerFiles = (nextAttachments) => { update('attachments', nextAttachments); if (task) onUpdateTask(task.id, (current) => ({ ...current, attachments: nextAttachments })); };
  const addPerformerFiles = (performerId, fileList) => { const files = Array.from(fileList).map((file) => ({ id: `${Date.now()}-${file.name}`, name: file.name, type: file.type, size: file.size, blob: file, uploadedById: performerId })); updatePerformerFiles([...draft.attachments, ...files]); };
  const removePerformerFile = (attachmentId) => updatePerformerFiles(draft.attachments.filter((attachment) => attachment.id !== attachmentId));
  return <main className="task-editor-screen"><header className="editor-header"><div><button className="back-button" onClick={onCancel}>← К задачам</button><h1>{task ? 'Редактирование задачи' : 'Новая задача'}</h1><p>Заполните данные задачи и сохраните изменения.</p></div><div className="editor-actions"><button className="secondary-button" onClick={onCancel}>Отмена</button><button className="primary-button" onClick={() => onSave(draft)} disabled={!draft.title.trim()}>Сохранить</button></div></header><div className="editor-layout"><section className="editor-card"><h2>Основные сведения</h2><label className="editor-field editor-title">Название задачи<input value={draft.title} onChange={(event) => update('title', event.target.value)} placeholder="Введите название задачи" autoFocus/></label><label className="editor-field">Описание<textarea value={draft.description} onChange={(event) => update('description', event.target.value)} placeholder="Опишите ожидаемый результат, требования и детали"/></label><section className="editor-attachments"><div className="editor-section-head"><div><h3>Файлы к описанию</h3><p className="editor-hint">Постановщик прикрепляет файлы; постановщик и исполнители могут их скачать.</p></div>{canManageAttachments ? <label className="attach-button">＋ Добавить файл<input type="file" multiple onChange={(event) => { addFiles(event.target.files); event.target.value = ''; }}/></label> : null}</div>{descriptionAttachments.length ? <div className="editor-files">{descriptionAttachments.map((attachment) => <div key={attachment.id}><span className="document-icon">▤</span><span>{attachment.name}</span>{canDownloadAttachments ? <button type="button" className="download-file" onClick={() => downloadAttachment(attachment)}>Скачать</button> : null}{canManageAttachments ? <button type="button" aria-label={`Удалить ${attachment.name}`} onClick={() => { if (window.confirm(`Удалить вложение «${attachment.name}»?`)) update('attachments', draft.attachments.filter((item) => item.id !== attachment.id)); }}>×</button> : null}</div>)}</div> : <p className="editor-hint">Файлы пока не добавлены.</p>}{!canDownloadAttachments ? <p className="editor-hint">Скачивание доступно постановщику и назначенным исполнителям.</p> : null}</section><div className="editor-grid"><label className="editor-field">Статус<select value={draft.status} onChange={(event) => update('status', event.target.value)}><option>В работе</option><option>Утверждение</option><option>Завершено</option><option>Просрочено</option></select></label><label className="editor-field">Приоритет<select value={draft.priority} onChange={(event) => update('priority', event.target.value)}><option>Высокий</option><option>Обычный</option></select></label><label className="editor-field">Дата срока<input type="date" value={draft.dueDate} onChange={(event) => update('dueDate', event.target.value)}/></label><label className="editor-field">Время срока<input type="time" value={draft.dueTime} onChange={(event) => update('dueTime', event.target.value)}/></label><label className="editor-field full-width">Постановщик задачи<select value={draft.ownerId} onChange={(event) => update('ownerId', event.target.value)}>{users.map((user) => <option key={user.id} value={user.id}>{user.name}</option>)}</select></label></div></section><section className="editor-card"><h2>Исполнители</h2><p className="editor-hint">Отметьте пользователей, которые будут выполнять задачу.</p><div className="choice-list">{users.map((user) => <label key={user.id}><input type="checkbox" checked={draft.performerIds.includes(user.id)} onChange={() => toggleListItem('performerIds', user.id)}/><Avatar user={user} small/>{user.name}</label>)}</div></section><section className="editor-card"><h2>Связанные документы</h2><p className="editor-hint">Выберите документы, которые относятся к этой задаче.</p><div className="choice-list">{documents.map((document) => <label key={document.id}><input type="checkbox" checked={draft.documents.includes(document.title)} onChange={() => toggleListItem('documents', document.title)}/><span className="document-icon">▤</span>{document.title}</label>)}</div></section></div><footer className="editor-footer"><button className="secondary-button" onClick={onCancel}>Отмена</button><button className="primary-button" onClick={() => onSave(draft)} disabled={!draft.title.trim()}>Сохранить задачу</button></footer></main>;
}

function TaskEditorScreen({ task, users, documents, currentUser, newTaskDefaults, onSave, onUpdateTask, onCancel }) {
  const emptyTask = { number: newTaskDefaults?.number ?? '', title: `Новая задача — ${currentUser.name}`, description: '', status: 'В работе', priority: 'Обычный', ownerId: currentUser.id, dueDate: new Date().toISOString().slice(0, 10), dueTime: '18:00', performerIds: [currentUser.id], documents: [], attachments: [], progress: 0, completedPerformerIds: [] };
  const [draft, setDraft] = useState(() => ({ ...emptyTask, ...task, performerIds: task?.performerIds ?? emptyTask.performerIds, documents: task?.documents ?? [], attachments: task?.attachments ?? [], completedPerformerIds: task?.completedPerformerIds ?? [] }));
  useEffect(() => { const heading = document.querySelector('.task-editor-screen .editor-header h1'); if (!heading) return; heading.textContent = `${task ? 'Задача' : 'Новая задача'} № ${draft.number || task?.number || ''}`; }, [draft.number, task]);
  const canEditTask = !task || task.ownerId === currentUser.id;
  useEffect(() => { if (!canEditTask) return; const section = document.querySelector('.editor-performers'); const header = section?.querySelector('.editor-section-head'); if (!section || !header) return; const holder = section.querySelector('.performer-dropdown-holder') ?? document.createElement('label'); holder.className = 'performer-dropdown-holder'; holder.textContent = 'Выбор исполнителя'; const select = document.createElement('select'); select.setAttribute('aria-label', 'Выбор исполнителя'); const placeholder = document.createElement('option'); placeholder.value = ''; placeholder.textContent = 'Выберите подразделение или сотрудника'; const departments = [...new Set(users.map((user) => user.department).filter(Boolean))]; const departmentGroup = document.createElement('optgroup'); departmentGroup.label = 'Подразделения'; departments.forEach((department) => { const option = document.createElement('option'); option.value = `department:${department}`; option.textContent = department; departmentGroup.append(option); }); const userGroup = document.createElement('optgroup'); userGroup.label = 'Сотрудники'; users.forEach((user) => { const option = document.createElement('option'); option.value = `user:${user.id}`; option.textContent = user.name; userGroup.append(option); }); select.append(placeholder, departmentGroup, userGroup); select.onchange = () => { const [kind, value] = select.value.split(':'); if (!value) return; setDraft((current) => { const performerIds = new Set(current.performerIds); if (kind === 'department') users.filter((user) => user.department === value).forEach((user) => performerIds.add(user.id)); if (kind === 'user') performerIds.add(value); return { ...current, performerIds: [...performerIds] }; }); select.value = ''; }; holder.append(select); if (!holder.parentNode) header.after(holder); }, [canEditTask, users]);
  useEffect(() => { const rows = document.querySelectorAll('.editor-performers .editor-performer-row'); const selectedPerformers = users.filter((user) => draft.performerIds.includes(user.id)); rows.forEach((row, index) => { const performer = selectedPerformers[index]; if (!performer) return; const control = row.querySelector('.editor-completion-control') ?? document.createElement('label'); control.className = 'editor-completion-control'; const input = document.createElement('input'); const canUpdateCompletion = canEditTask || performer.id === currentUser.id; input.type = 'checkbox'; input.checked = draft.completedPerformerIds.includes(performer.id); input.disabled = !canUpdateCompletion; input.onchange = () => { const isCompleted = input.checked; const applyCompletion = (current) => { const completed = new Set(current.completedPerformerIds ?? []); if (isCompleted) completed.add(performer.id); else completed.delete(performer.id); return { ...current, completedPerformerIds: [...completed] }; }; setDraft(applyCompletion); if (task && canUpdateCompletion) onUpdateTask(task.id, applyCompletion); }; control.replaceChildren(input, document.createTextNode('Выполнено')); if (!control.parentNode) row.insertBefore(control, row.querySelector('.editor-performer-actions')); }); }, [canEditTask, currentUser.id, draft.completedPerformerIds, draft.performerIds, onUpdateTask, task, users]);
  const update = (field, value) => { if (field !== 'ownerId') setDraft((current) => ({ ...current, [field]: value })); };
  const toggleItem = (field, value) => update(field, draft[field].includes(value) ? draft[field].filter((item) => item !== value) : [...draft[field], value]);
  const downloadFile = (attachment) => { if (!attachment.blob) return; const url = URL.createObjectURL(attachment.blob); const link = document.createElement('a'); link.href = url; link.download = attachment.name; link.click(); URL.revokeObjectURL(url); };
  const updateAttachments = (attachments) => { update('attachments', attachments); if (task) onUpdateTask(task.id, (current) => ({ ...current, attachments })); };
  const addPerformerFiles = (performerId, files) => { const newFiles = Array.from(files).map((file) => ({ id: `${Date.now()}-${file.name}`, name: file.name, type: file.type, size: file.size, blob: file, uploadedById: performerId })); updateAttachments([...draft.attachments, ...newFiles]); };
  const removePerformerFile = (attachmentId) => updateAttachments(draft.attachments.filter((attachment) => attachment.id !== attachmentId));
  const descriptionAttachments = draft.attachments.filter((attachment) => !attachment.uploadedById || attachment.uploadedById === draft.ownerId);
  const addDescriptionFiles = (files) => { const newFiles = Array.from(files).map((file) => ({ id: `${Date.now()}-${file.name}`, name: file.name, type: file.type, size: file.size, blob: file, uploadedById: currentUser.id })); updateAttachments([...draft.attachments, ...newFiles]); };
  return <main className="task-editor-screen"><header className="editor-header"><div><button className="back-button" onClick={onCancel}>← К задачам</button><h1>{task ? 'Задача' : 'Новая задача'}</h1><p>{canEditTask ? 'Заполните данные и сохраните изменения.' : 'Данные задачи доступны для просмотра. Вы можете работать только со своими файлами.'}</p></div>{canEditTask ? <div className="editor-actions"><button className="secondary-button" onClick={onCancel}>Отмена</button><button className="primary-button" disabled={!draft.title.trim()} onClick={() => onSave(draft)}>Сохранить</button></div> : null}</header><div className="editor-layout"><section className="editor-card"><h2>Основные сведения</h2><label className="editor-field editor-title">Название задачи<input disabled={!canEditTask} value={draft.title} onChange={(event) => update('title', event.target.value)}/></label><label className="editor-field">Описание<textarea disabled={!canEditTask} value={draft.description} onChange={(event) => update('description', event.target.value)}/></label><div className="editor-attachments"><div className="editor-section-head"><div><h3>Файлы к описанию</h3><p className="editor-hint">Постановщик добавляет и удаляет файлы. Постановщик и исполнители могут их скачать.</p></div>{canEditTask ? <label className="attach-button">＋ Добавить файл<input type="file" multiple onChange={(event) => { addDescriptionFiles(event.target.files); event.target.value = ''; }}/></label> : null}</div>{descriptionAttachments.map((attachment) => <div className="editor-file-line" key={attachment.id}><span>{attachment.name}</span>{(canEditTask || draft.performerIds.includes(currentUser.id)) ? <button type="button" onClick={() => downloadFile(attachment)}>Скачать</button> : null}</div>)}{!descriptionAttachments.length ? <p className="editor-hint">Файлы пока не добавлены.</p> : null}</div><div className="editor-grid"><label className="editor-field">Статус<select disabled={!canEditTask} value={draft.status} onChange={(event) => update('status', event.target.value)}><option>В работе</option><option>Утверждение</option><option>Завершено</option><option>Просрочено</option></select></label><label className="editor-field">Приоритет<select disabled={!canEditTask} value={draft.priority} onChange={(event) => update('priority', event.target.value)}><option>Высокий</option><option>Обычный</option></select></label><label className="editor-field">Дата срока<input disabled={!canEditTask} type="date" value={draft.dueDate} onChange={(event) => update('dueDate', event.target.value)}/></label><label className="editor-field">Время срока<input disabled={!canEditTask} type="time" value={draft.dueTime} onChange={(event) => update('dueTime', event.target.value)}/></label><label className="editor-field full-width">Постановщик задачи<select disabled={!canEditTask} value={draft.ownerId} onChange={(event) => update('ownerId', event.target.value)}>{users.map((user) => <option key={user.id} value={user.id}>{user.name}</option>)}</select></label></div></section><section className="editor-card editor-performers"><div className="editor-section-head"><div><h2>Исполнители</h2><p className="editor-hint">У каждого исполнителя — отдельные файлы. Постановщик и исполнитель могут добавлять и удалять файлы исполнителя.</p></div>{canEditTask ? <button className="secondary-button select-all-performers" type="button" disabled={draft.performerIds.length === users.length} onClick={() => update('performerIds', users.map((user) => user.id))}>Все</button> : null}</div>{canEditTask ? <div className="choice-list performer-selection">{users.map((user) => <label key={user.id}><input type="checkbox" checked={draft.performerIds.includes(user.id)} onChange={() => toggleItem('performerIds', user.id)}/><Avatar user={user} small/>{user.name}</label>)}</div> : null}<div className="editor-performer-files">{users.filter((user) => draft.performerIds.includes(user.id)).map((performer) => { const isCurrentUser = performer.id === currentUser.id; const performerFiles = draft.attachments.filter((attachment) => attachment.uploadedById === performer.id); const canViewFiles = canEditTask || isCurrentUser; const canManagePerformerFiles = canEditTask || isCurrentUser; return <div className="editor-performer-row" key={performer.id}><span className="owner"><Avatar user={performer} small/>{performer.name}</span><div className="editor-performer-actions">{canManagePerformerFiles ? <label className="row-file-button">＋ Файл<input type="file" multiple onChange={(event) => { addPerformerFiles(performer.id, event.target.files); event.target.value = ''; }}/></label> : null}{canViewFiles ? performerFiles.map((attachment) => <span className="performer-file" key={attachment.id}><button type="button" className="performer-file-download" onClick={() => downloadFile(attachment)}>Скачать {attachment.name}</button>{canManagePerformerFiles ? <button type="button" aria-label={`Удалить ${attachment.name}`} onClick={() => { if (window.confirm(`Удалить вложение «${attachment.name}»?`)) removePerformerFile(attachment.id); }}>×</button> : null}</span>) : null}{canViewFiles && !performerFiles.length ? <span className="muted">Файлы не добавлены</span> : null}</div></div>; })}</div></section><section className="editor-card"><h2>Связанные документы</h2><div className="choice-list">{documents.map((document) => <label key={document.id}><input disabled={!canEditTask} type="checkbox" checked={draft.documents.includes(document.title)} onChange={() => toggleItem('documents', document.title)}/><span className="document-icon">▤</span>{document.title}</label>)}</div></section></div>{canEditTask ? <footer className="editor-footer"><button className="secondary-button" onClick={onCancel}>Отмена</button><button className="primary-button" disabled={!draft.title.trim()} onClick={() => onSave(draft)}>Сохранить задачу</button></footer> : null}</main>;
}

function TasksView({ tasks, users, documents, currentUser, query, focusedTaskId, onAddTask, onCopyTask, onUpdateTask, onDeleteTask }) {
  const [selectedId, setSelectedId] = useState(tasks[0]?.id);
  const [status, setStatus] = useState('Все');
  const [priority, setPriority] = useState('Все');
  const [ownerId, setOwnerId] = useState('Все');
  const [onlyMine, setOnlyMine] = useState(false);
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [dateFilterOpen, setDateFilterOpen] = useState(false);
  const [page, setPage] = useState(1);
  const [editRequest, setEditRequest] = useState(0);
  const [editorMode, setEditorMode] = useState(null);
  const filtered = useMemo(() => tasks.filter((task) => (
    (status === 'Все' || task.status === status)
    && (priority === 'Все' || task.priority === priority)
    && (ownerId === 'Все' || task.ownerId === ownerId)
    && (!onlyMine || task.ownerId === currentUser.id || (task.performerIds ?? []).includes(currentUser.id))
    && (!dateFrom || task.dueDate >= dateFrom)
    && (!dateTo || task.dueDate <= dateTo)
    && task.title.toLowerCase().includes(query.toLowerCase())
  )), [tasks, status, priority, ownerId, onlyMine, dateFrom, dateTo, currentUser.id, query]);
  useEffect(() => { if (focusedTaskId && tasks.some((task) => task.id === focusedTaskId)) setSelectedId(focusedTaskId); }, [focusedTaskId, tasks]);
  useEffect(() => { if (!filtered.some((task) => task.id === selectedId)) setSelectedId(filtered[0]?.id); }, [filtered, selectedId]);
  useEffect(() => { setPage(1); }, [status, priority, ownerId, onlyMine, dateFrom, dateTo, query]);
  const completed = filtered.filter((task) => task.status === 'Завершено').length;
  const working = filtered.filter((task) => task.status === 'В работе').length;
  const overdue = filtered.filter((task) => task.status === 'Просрочено').length;
  const selectedTask = tasks.find((task) => task.id === selectedId);
  const selected = selectedTask ? { ...selectedTask, taskStats: { total: filtered.length, working, overdue, completed } } : null;
  const pageSize = 10;
  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
  const currentPage = Math.min(page, pageCount);
  const pageStart = (currentPage - 1) * pageSize;
  const pagedTasks = filtered.slice(pageStart, pageStart + pageSize);
  const pageNumbers = Array.from({ length: pageCount }, (_, index) => index + 1);
  const canManageSelectedTask = Boolean(selected && canManageTask(currentUser, selected));
  const addPerformer = (task, performerId) => onUpdateTask(task.id, (current) => ({ ...current, performerIds: [...new Set([...(current.performerIds ?? []), performerId])] }));
  const attachFile = (task, file) => onUpdateTask(task.id, (current) => ({ ...current, attachments: [...(current.attachments ?? []), { id: `${Date.now()}-${file.name}`, name: file.name, type: file.type, size: file.size, blob: file, uploadedById: currentUser.id }] }));
  const removeAttachment = (task, attachmentId) => onUpdateTask(task.id, (current) => ({ ...current, attachments: (current.attachments ?? []).filter((attachment) => attachment.id !== attachmentId) }));
  if (editorMode) return <TaskEditorScreen task={editorMode === 'edit' ? selected : null} newTaskDefaults={editorMode === 'new' ? { number: nextTaskNumber(tasks) } : undefined} users={users} documents={documents} currentUser={currentUser} onUpdateTask={onUpdateTask} onCancel={() => setEditorMode(null)} onSave={async (draft) => { if (editorMode === 'new') await onAddTask(draft); else await onUpdateTask(draft.id, () => draft); setEditorMode(null); }}/>;
  return <div className="split-screen"><main className="workspace"><div className="page-title-row"><div><h1>Задачи</h1><p className="summary">Всего задач: <b>{filtered.length}</b><span/>В работе: <b className="blue-text">{working}</b><span/>Просрочено: <b className="red-text">{overdue}</b><span/>Завершено: <b className="green-text">{completed}</b></p></div><div className="task-toolbar"><button className="secondary-button" disabled={!canManageSelectedTask} onClick={() => setEditorMode('edit')}>Редактировать</button><button className="delete-toolbar-button" disabled={!canManageSelectedTask} onClick={() => { if (window.confirm(`Удалить задачу «${selected.title}»?`)) onDeleteTask(selected.id); }}>Удалить</button><button className="secondary-button" disabled={!selected} onClick={() => onCopyTask(selected)}>Копировать</button><button className="primary-button" onClick={() => setEditorMode('new')}>Новая задача <span>＋</span></button></div></div><section className="trend"><div><h3>Динамика по статусам</h3><svg viewBox="0 0 600 100" role="img" aria-label="Динамика задач"><path d="M6 78H594M6 51H594M6 24H594" className="chart-grid"/><polyline points="8,65 105,54 202,54 299,45 396,58 493,44 590,45" className="chart-line blue-line"/><polyline points="8,70 105,70 202,71 299,66 396,70 493,65 590,66" className="chart-line amber-line"/><polyline points="8,79 105,79 202,79 299,77 396,79 493,77 590,77" className="chart-line green-line"/></svg></div><ul className="chart-legend"><li><i className="blue"/>В работе</li><li><i className="amber"/>Просрочено</li><li><i className="green"/>Завершено</li></ul></section><div className="filter-row"><label>Статус:<select value={status} onChange={(event) => setStatus(event.target.value)}><option>Все</option><option>В работе</option><option>Утверждение</option><option>Завершено</option><option>Просрочено</option></select></label><label>Приоритет:<select value={priority} onChange={(event) => setPriority(event.target.value)}><option>Все</option><option>Высокий</option><option>Обычный</option></select></label><label>Постановщик задачи:<select value={ownerId} onChange={(event) => setOwnerId(event.target.value)}><option value="Все">Все</option>{users.map((user) => <option key={user.id} value={user.id}>{user.name}</option>)}</select></label><label className="mine-filter"><input type="checkbox" checked={onlyMine} onChange={(event) => setOnlyMine(event.target.checked)}/>Мои</label><button type="button" className="filter-button" aria-expanded={dateFilterOpen} onClick={() => setDateFilterOpen((open) => !open)}>⌘ Фильтр даты</button>{dateFilterOpen ? <div className="date-range-filter"><label>С<input type="date" value={dateFrom} max={dateTo || undefined} onChange={(event) => setDateFrom(event.target.value)}/></label><label>По<input type="date" value={dateTo} min={dateFrom || undefined} onChange={(event) => setDateTo(event.target.value)}/></label>{dateFrom || dateTo ? <button type="button" onClick={() => { setDateFrom(''); setDateTo(''); }}>Сбросить</button> : null}</div> : null}</div><TaskTable tasks={pagedTasks} users={users} selectedId={selectedId} onSelect={setSelectedId} onEdit={(task) => { setSelectedId(task.id); if (canManageTask(currentUser, task)) setEditorMode('edit'); }}/><footer className="pagination"><span>{filtered.length ? `${pageStart + 1}–${Math.min(pageStart + pageSize, filtered.length)} из ${filtered.length}` : '0 из 0'}</span><div><button type="button" aria-label="Предыдущая страница" disabled={currentPage === 1} onClick={() => setPage((current) => Math.max(1, current - 1))}>‹</button>{pageNumbers.map((number) => <button type="button" key={number} className={number === currentPage ? 'current' : ''} aria-label={`Страница ${number}`} onClick={() => setPage(number)}>{number}</button>)}<button type="button" aria-label="Следующая страница" disabled={currentPage === pageCount || !filtered.length} onClick={() => setPage((current) => Math.min(pageCount, current + 1))}>›</button></div></footer></main><TaskDetails task={selected} users={users} currentUser={currentUser} editRequest={editRequest} onAddPerformer={addPerformer} onAttachFile={attachFile} onRemoveAttachment={removeAttachment} onUpdateTask={onUpdateTask} onDeleteTask={onDeleteTask}/></div>;
}

function DirectoriesView({ directories, users, query, onSaveDirectory }) {
  const [selected, setSelected] = useState(directories[0]?.id);
  const [localQuery, setLocalQuery] = useState('');
  const [editor, setEditor] = useState(null);
  const [menuCode, setMenuCode] = useState(null);
  const [moreOpen, setMoreOpen] = useState(false);
  const [notice, setNotice] = useState('');
  const [selectedRowCode, setSelectedRowCode] = useState(null);
  const active = directories.find((directory) => directory.id === selected) ?? directories[0];
  const filterValue = `${query} ${localQuery}`.trim().toLowerCase();
  const valueLabel = active?.name === 'Контрагенты' ? 'Статус' : active?.name === 'Роли и права' ? 'Права доступа' : 'Руководитель';
  const rows = (active?.rows ?? []).filter((row) => !filterValue || [row.name, row.code, row.owner].some((value) => value.toLowerCase().includes(filterValue)));
  const nextCode = () => String((active?.rows ?? []).reduce((maximum, row) => /^\d+$/.test(String(row.code)) ? Math.max(maximum, Number(row.code)) : maximum, 0) + 1);
  const emptyDraft = (group = false) => ({ name: group ? 'Новая группа' : '', code: nextCode(), owner: '', group });
  const saveRow = (event) => { event.preventDefault(); const draft = editor?.draft; if (!draft?.name.trim() || !draft.code.trim() || !draft.owner.trim()) { setNotice('Заполните наименование и реквизит. Код присваивается автоматически.'); return; } const normalized = { ...draft, name: draft.name.trim(), code: String(draft.code).trim(), owner: draft.owner.trim() }; const exists = editor.mode === 'edit'; const duplicate = active.rows.some((row) => row.code === normalized.code && row.code !== editor.originalCode); if ((!/^\d+$/.test(normalized.code) && normalized.code !== editor.originalCode) || duplicate) { setNotice('Код должен быть уникальным целым числом.'); return; } const nextRows = exists ? active.rows.map((row) => row.code === editor.originalCode ? normalized : row) : [...active.rows, normalized]; onSaveDirectory(active.id, nextRows); setEditor(null); setNotice(exists ? 'Запись изменена.' : normalized.group ? 'Группа создана.' : 'Запись создана.'); };
  const deleteRow = (row) => { if (!row) return; if (active.name === 'Подразделения' && users.some((user) => user.department === row.name)) { setNotice(`Нельзя удалить «${row.name}»: подразделение назначено пользователям.`); return; } if (!window.confirm(`Удалить запись «${row.name}»?`)) return; onSaveDirectory(active.id, active.rows.filter((item) => item.code !== row.code)); setSelectedRowCode(null); setMenuCode(null); setNotice('Запись удалена.'); };
  const selectedRow = active?.rows.find((row) => row.code === selectedRowCode);
  return <main className="single-workspace directory-workspace"><div className="page-title-row"><div><h1>Справочники</h1><p>Единые классификаторы и организационные данные.</p></div></div><div className="directory-layout one-c-layout"><aside className="directory-menu directory-catalog"><div className="catalog-caption">Справочники</div>{directories.map((directory) => <button key={directory.id} onClick={() => { setSelected(directory.id); setLocalQuery(''); setEditor(null); setMenuCode(null); setSelectedRowCode(null); setNotice(''); }} className={directory.id === selected ? 'active' : ''}><span>▦</span>{directory.name}<b>{directory.rows.length}</b></button>)}</aside><section className="directory-content one-c-table"><div className="content-heading"><div><p className="form-breadcrumb">Справочники / {active?.name}</p><h2>{active?.name}</h2></div><div className="directory-toolbar"><button className="primary-button" onClick={() => setEditor({ mode: 'new', draft: emptyDraft() })}>Создать</button><button className="secondary-button" onClick={() => setEditor({ mode: 'new', draft: emptyDraft(true) })}>Создать группу</button><button className="directory-delete-button" disabled={!selectedRow} onClick={() => deleteRow(selectedRow)}>Удалить</button><div className="directory-more"><button className="secondary-button" onClick={() => setMoreOpen((current) => !current)}>Ещё ▾</button>{moreOpen ? <div className="directory-popover"><button onClick={() => { setLocalQuery(''); setMoreOpen(false); setNotice('Отбор снят.'); }}>Снять отбор</button><button onClick={() => { setMoreOpen(false); setNotice('Список обновлён.'); }}>Обновить список</button></div> : null}</div></div></div>{editor ? <form className="directory-editor" onSubmit={saveRow}><strong>{editor.mode === 'edit' ? 'Изменение записи' : editor.draft.group ? 'Новая группа' : 'Новая запись'}</strong><label>Наименование<input autoFocus value={editor.draft.name} onChange={(event) => setEditor((current) => ({ ...current, draft: { ...current.draft, name: event.target.value } }))}/></label><label>Код<input value={editor.draft.code} onChange={(event) => setEditor((current) => ({ ...current, draft: { ...current.draft, code: event.target.value } }))}/></label><label>{valueLabel}<input value={editor.draft.owner} onChange={(event) => setEditor((current) => ({ ...current, draft: { ...current.draft, owner: event.target.value } }))}/></label><button className="primary-button" type="submit">Записать</button><button className="secondary-button" type="button" onClick={() => setEditor(null)}>Отмена</button></form> : null}<div className="table-command-bar"><label className="directory-search"><span>⌕</span><input value={localQuery} onChange={(event) => setLocalQuery(event.target.value)} placeholder="Найти в справочнике" aria-label="Поиск в справочнике"/></label><span>{rows.length} из {active?.rows.length ?? 0}</span><button className="table-icon-button" title="Обновить" onClick={() => setNotice('Список обновлён.')}>↻</button></div>{notice ? <p className="directory-notice" role="status">{notice}</p> : null}<div className="one-c-table-wrap"><table><thead><tr><th className="row-number">№</th><th className="hierarchy-cell"/><th>Код</th><th>Наименование</th><th>{valueLabel}</th><th className="actions-cell"/></tr></thead><tbody>{rows.length ? rows.map((row, index) => <tr key={row.code} className={row.code === selectedRowCode ? 'selected' : ''} onClick={() => setSelectedRowCode(row.code)}><td className="row-number">{index + 1}</td><td className="hierarchy-cell"><span className="row-marker">{row.group ? '▾' : '▸'}</span></td><td className="directory-code">{row.code}</td><td><button className="directory-name-button" onClick={() => { setSelectedRowCode(row.code); setEditor({ mode: 'edit', originalCode: row.code, draft: { ...row } }); }}>{row.name}</button></td><td>{row.owner}</td><td className="actions-cell"><div className="row-actions"><button className="more-button" aria-label={`Действия: ${row.name}`} onClick={(event) => { event.stopPropagation(); setMenuCode((current) => current === row.code ? null : row.code); }}>•••</button>{menuCode === row.code ? <div className="row-popover"><button onClick={() => { setEditor({ mode: 'edit', originalCode: row.code, draft: { ...row } }); setMenuCode(null); }}>Изменить</button><button className="danger-action" onClick={() => deleteRow(row)}>Удалить</button></div> : null}</div></td></tr>) : <tr><td colSpan="6" className="directory-empty">Записи не найдены.</td></tr>}</tbody></table></div><footer className="directory-status-bar"><span>Список</span><span>Выберите строку, затем нажмите «Удалить»</span></footer></section></div></main>;
}

function DocumentEditor({ document, category, currentUser, onSave, onCancel }) {
  const [draft, setDraft] = useState(() => document ? { ...document, attachment: document.attachment ?? null } : { title: '', type: category === 'normative' ? 'Регламент' : 'Инструкция', number: '', status: 'Действует', updated: new Date().toISOString().slice(0, 10), attachment: null });
  const [notice, setNotice] = useState('');
  const change = (field) => (event) => setDraft((current) => ({ ...current, [field]: event.target.value }));
  const submit = async (event) => { event.preventDefault(); if (!draft.title.trim()) { setNotice('Укажите наименование документа.'); return; } await onSave({ ...draft, id: document?.id ?? `d${Date.now()}`, title: draft.title.trim(), type: draft.type.trim() || 'Документ', number: draft.number.trim() || 'Без номера', status: draft.status, updated: draft.updated, owner: document?.owner ?? currentUser.name, category, attachment: draft.attachment }); };
  return <main className="single-workspace document-editor-screen"><header className="editor-header"><div><button className="back-button" onClick={onCancel}>← К документам</button><h1>{document ? 'Редактирование документа' : 'Новый документ'}</h1><p>Заполните карточку и при необходимости прикрепите файл.</p></div><div className="editor-actions"><button className="secondary-button" onClick={onCancel}>Отмена</button><button className="primary-button" onClick={submit}>Сохранить</button></div></header><form className="document-card" onSubmit={submit}><section><h2>Основные сведения</h2><div className="document-card-grid"><label className="document-card-wide">Наименование документа<input autoFocus value={draft.title} onChange={change('title')} placeholder="Например, Регламент обработки обращений"/></label><label>Вид документа<input value={draft.type} onChange={change('type')} placeholder="Регламент, инструкция, политика"/></label><label>Номер документа<input value={draft.number} onChange={change('number')} placeholder="Например, РД-01/2026"/></label><label>Статус<select value={draft.status} onChange={change('status')}><option>Действует</option><option>На согласовании</option><option>Требует пересмотра</option></select></label><label>Дата документа<input type="date" value={draft.updated} onChange={change('updated')}/></label><label>Ответственный<input value={draft.owner || currentUser.name} disabled/></label></div></section><section><h2>Файл документа</h2><p>Прикреплённый файл будет доступен для скачивания из списка документов.</p><label className="document-upload"><span>＋ {draft.attachment ? 'Заменить файл' : 'Выбрать файл'}</span><input type="file" onChange={(event) => { const [file] = event.target.files; setDraft((current) => ({ ...current, attachment: file ? { name: file.name, type: file.type, size: file.size, blob: file } : current.attachment })); }}/></label>{draft.attachment ? <div className="document-selected-file"><span>▤</span><strong>{draft.attachment.name}</strong><small>{Math.max(1, Math.round(draft.attachment.size / 1024))} КБ</small><button type="button" onClick={() => setDraft((current) => ({ ...current, attachment: null }))}>Удалить</button></div> : <small className="document-upload-hint">Файл пока не выбран.</small>}</section><footer><button className="secondary-button" type="button" onClick={onCancel}>Отмена</button><button className="primary-button" type="submit">Сохранить документ</button>{notice ? <p role="status">{notice}</p> : null}</footer></form></main>;
}

function DocumentsView({ documents, query, category, currentUser, onAddDocument, onUpdateDocument, onDeleteDocument }) {
  const [mode, setMode] = useState(null);
  const [selectedId, setSelectedId] = useState(null);
  const [statusFilter, setStatusFilter] = useState('Все документы');
  const isNormative = (document) => document.category ? document.category === 'normative' : ['Регламент', 'Политика'].includes(document.type);
  const title = category === 'normative' ? 'Нормативные документы' : 'Внутренние документы';
  const description = category === 'normative' ? 'Регламенты и политики, обязательные для применения в организации.' : 'Положения, инструкции и рабочие документы подразделений.';
  const categoryRows = documents.filter((document) => isNormative(document) === (category === 'normative') && document.title.toLowerCase().includes(query.toLowerCase()));
  const rows = statusFilter === 'Все документы' ? categoryRows : categoryRows.filter((document) => document.status === statusFilter);
  const download = (document) => { if (!document.attachment?.blob) return; const url = URL.createObjectURL(document.attachment.blob); const link = document.createElement('a'); link.href = url; link.download = document.attachment.name; link.click(); URL.revokeObjectURL(url); };
  const selectedDocument = rows.find((document) => document.id === selectedId);
  const remove = async () => { if (!selectedDocument || !window.confirm(`Удалить документ «${selectedDocument.title}»?`)) return; await onDeleteDocument(selectedDocument.id); setSelectedId(null); };
  if (mode) return <DocumentEditor document={mode === 'edit' ? selectedDocument : null} category={category} currentUser={currentUser} onCancel={() => setMode(null)} onSave={async (document) => { if (mode === 'edit') await onUpdateDocument(document); else await onAddDocument(document); setMode(null); setSelectedId(document.id); }}/>;
  return <main className="single-workspace"><div className="page-title-row"><div><h1>{title}</h1><p>{description}</p></div><div className="document-actions-toolbar"><button className="primary-button" onClick={() => setMode('new')}>Новый документ <span>＋</span></button><button className="secondary-button" disabled={!selectedDocument} onClick={() => setMode('edit')}>Редактировать</button><button className="directory-delete-button" disabled={!selectedDocument} onClick={remove}>Удалить</button></div></div><section className="documents-dashboard"><div className="document-filters">{['Все документы', 'Действует', 'На согласовании', 'Требует пересмотра'].map((filter) => <button key={filter} className={statusFilter === filter ? 'selected' : ''} onClick={() => { setStatusFilter(filter); setSelectedId(null); }}>{filter}{filter === 'Все документы' ? <b>{categoryRows.length}</b> : null}</button>)}</div><div className="document-table"><table><thead><tr><th>Документ</th><th>Номер</th><th>Статус</th><th>Ответственный</th><th>Обновлён</th><th/></tr></thead><tbody>{rows.length ? rows.map((document) => <tr key={document.id} className={selectedId === document.id ? 'selected' : ''} onClick={() => setSelectedId(document.id)} onDoubleClick={() => { setSelectedId(document.id); setMode('edit'); }}><td><span className="file-badge">{document.attachment?.name?.split('.').pop()?.toUpperCase() || 'DOC'}</span><div><strong>{document.title}</strong><small>{document.type}</small></div></td><td>{document.number}</td><td><span className={`document-status ${document.status === 'Действует' ? 'success' : document.status === 'На согласовании' ? 'pending' : 'attention'}`}>{document.status}</span></td><td>{document.owner}</td><td>{dateText(document.updated)}</td><td>{document.attachment ? <button className="more-button" onClick={(event) => { event.stopPropagation(); download(document); }}>Скачать</button> : <button className="more-button" disabled>—</button>}</td></tr>) : <tr><td colSpan="6" className="directory-empty">Документы по выбранному фильтру не найдены.</td></tr>}</tbody></table></div></section></main>;
}

function DirectoriesMenuView({ directories, onSaveDirectory }) {
  const [directoryId, setDirectoryId] = useState(directories[0]?.id);
  return <div className="directories-menu-layout"><aside className="directories-hover-list"><h2>Список справочников</h2>{directories.map((directory) => <button key={directory.id} className={directory.id === directoryId ? 'active' : ''} onClick={() => setDirectoryId(directory.id)}><span>▦ {directory.name}</span><small>{directory.rows.length} записей</small><em>Открыть →</em></button>)}</aside><DirectoryRecordsView directories={directories} selectedDirectoryId={directoryId} onSaveDirectory={onSaveDirectory}/></div>;
}

function DirectoryRecordsView({ directories, selectedDirectoryId, onSaveDirectory }) {
  const [directoryId, setDirectoryId] = useState(directories[0]?.id); const [selectedCode, setSelectedCode] = useState(null); const [mode, setMode] = useState(null); const [draft, setDraft] = useState(null); const [notice, setNotice] = useState('');
  useEffect(() => { if (selectedDirectoryId) { setDirectoryId(selectedDirectoryId); setSelectedCode(null); } }, [selectedDirectoryId]);
  const directory = directories.find((item) => item.id === directoryId) ?? directories[0];
  const fields = directory?.fields?.length ? directory.fields.map((field) => field.id === 'code' ? { ...field, name: 'Код', type: 'числовой' } : field) : [{ id: 'code', name: 'Код', type: 'числовой' }, { id: 'name', name: 'Наименование', type: 'текстовый' }, { id: 'owner', name: 'Реквизит', type: 'текстовый' }];
  const selected = directory?.rows.find((row) => row.code === selectedCode);
  const nextCode = () => String((directory?.rows ?? []).reduce((max, row) => /^\d+$/.test(String(row.code)) ? Math.max(max, Number(row.code)) : max, 0) + 1);
  const begin = (nextMode) => { if (nextMode !== 'new' && !selected) { setNotice('Выберите запись в таблице.'); return; } setDraft(nextMode === 'new' ? Object.fromEntries(fields.map((field) => [field.id, field.id === 'code' ? nextCode() : ''])) : { ...selected }); setMode(nextMode); };
  const save = async (event) => { event.preventDefault(); if (!draft.name?.trim()) { setNotice('Заполните наименование.'); return; } const nextRows = mode === 'new' ? [...directory.rows, draft] : directory.rows.map((row) => row.code === selected.code ? draft : row); await onSaveDirectory(directory.id, nextRows); setSelectedCode(draft.code); setMode(null); setNotice(mode === 'new' ? 'Запись создана.' : 'Запись изменена.'); };
  const remove = async () => { await onSaveDirectory(directory.id, directory.rows.filter((row) => row.code !== selected.code)); setSelectedCode(null); setMode(null); setNotice('Запись удалена.'); };
  return <main className="single-workspace directory-workspace"><div className="page-title-row"><div><h1>Справочники</h1><p>Работа с записями справочников.</p></div><div className="directory-actions-toolbar"><button className="primary-button" onClick={() => begin('new')}>Создать</button><button className="secondary-button" disabled={!selected} onClick={() => begin('edit')}>Редактировать</button><button className="directory-delete-button" disabled={!selected} onClick={() => begin('delete')}>Удалить</button></div></div><section className="existing-directories-card"><label className="directory-select-label">Справочник<select value={directory?.id ?? ''} onChange={(event) => { setDirectoryId(event.target.value); setSelectedCode(null); }}>{directories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><table><thead><tr>{fields.map((field) => <th key={field.id}>{field.name}</th>)}</tr></thead><tbody>{directory?.rows.map((row) => <tr key={row.code} className={row.code === selectedCode ? 'selected' : ''} onClick={() => setSelectedCode(row.code)} onDoubleClick={() => { setSelectedCode(row.code); setDraft({ ...row }); setMode('edit'); }}>{fields.map((field) => <td key={field.id}>{row[field.id] ?? ''}</td>)}</tr>)}</tbody></table></section>{mode ? <div className="directory-window-backdrop"><section className="directory-action-window">{mode === 'delete' ? <><h2>Удаление записи</h2><p>Удалить выбранную запись?</p><div><button className="field-delete-button" onClick={remove}>Удалить</button><button className="secondary-button" onClick={() => setMode(null)}>Отмена</button></div></> : <form onSubmit={save}><h2>{mode === 'new' ? 'Новая запись' : 'Редактирование записи'}</h2>{fields.map((field) => <label key={field.id}>{field.name}{field.id === 'code' ? <input readOnly value={draft.code}/> : field.type === 'файл' ? <input type="file" onChange={(event) => setDraft((current) => ({ ...current, [field.id]: event.target.files?.[0]?.name ?? '' }))}/> : <input type={field.type === 'числовой' ? 'number' : field.type === 'дата' ? 'date' : field.type === 'телефон' ? 'tel' : 'text'} value={draft[field.id] ?? ''} onChange={(event) => setDraft((current) => ({ ...current, [field.id]: event.target.value }))}/>}</label>)}<div><button className="primary-button" type="submit">Сохранить</button><button className="secondary-button" type="button" onClick={() => setMode(null)}>Отмена</button></div></form>}</section></div> : null}{notice ? <p className="user-message">{notice}</p> : null}</main>;
}

function DirectoryManager({ directories, users, onCreateDirectory, onUpdateDirectory, onDeleteDirectory }) {
  const [selectedId, setSelectedId] = useState(null); const [mode, setMode] = useState(null); const [draft, setDraft] = useState(null); const [notice, setNotice] = useState('');
  const selected = directories.find((item) => item.id === selectedId);
  const normalizeFields = (directory) => directory?.fields?.length ? directory.fields.map((field) => field.id === 'code' ? { ...field, name: 'Код', type: 'числовой' } : field) : [{ id: 'code', name: 'Код', type: 'числовой' }, { id: 'name', name: 'Наименование', type: 'текстовый' }, { id: 'owner', name: 'Реквизит', type: 'текстовый' }];
  const begin = (nextMode) => { if (nextMode !== 'new' && !selected) { setNotice('Сначала выберите справочник.'); return; } setDraft(nextMode === 'new' ? { id: `directory-${Date.now()}`, name: '', rows: [], fields: [{ id: 'code', name: 'Код', type: 'числовой' }, { id: 'name', name: 'Наименование', type: 'текстовый' }] } : { ...selected, fields: normalizeFields(selected) }); setMode(nextMode); };
  const changeField = (id, change) => setDraft((current) => ({ ...current, fields: current.fields.map((field) => field.id === id ? { ...field, ...change } : field) }));
  const addField = () => setDraft((current) => ({ ...current, fields: [...current.fields, { id: `field-${Date.now()}`, name: '', type: 'текстовый' }] }));
  const moveField = (from, direction) => setDraft((current) => { const to = from + direction; if (from <= 0 || to <= 0 || to >= current.fields.length) return current; const fields = [...current.fields]; [fields[from], fields[to]] = [fields[to], fields[from]]; return { ...current, fields }; });
  useEffect(() => { if (!mode || !draft) return; const rows = document.querySelectorAll('.directory-action-window .schema-field-row'); rows.forEach((row, index) => { const field = draft.fields[index]; const typeSelect = row.querySelector('select'); if (typeSelect && ![...typeSelect.options].some((option) => option.value === 'справочник')) { const option = document.createElement('option'); option.value = 'справочник'; option.textContent = 'справочник'; typeSelect.append(option); } const existing = row.querySelector('.field-order-controls'); if (index === 0) { existing?.remove(); row.querySelector('.field-directory-source')?.remove(); return; } const controls = existing ?? document.createElement('span'); controls.className = 'field-order-controls'; let [up, down] = controls.querySelectorAll('button'); if (!up || !down) { controls.replaceChildren(); up = document.createElement('button'); up.type = 'button'; up.textContent = '↑'; down = document.createElement('button'); down.type = 'button'; down.textContent = '↓'; controls.append(up, down); row.appendChild(controls); } up.disabled = index === 1; up.onclick = () => moveField(index, -1); down.disabled = index === draft.fields.length - 1; down.onclick = () => moveField(index, 1); const currentReference = row.querySelector('.field-directory-source'); if (field?.type !== 'справочник') { currentReference?.remove(); return; } const source = currentReference ?? document.createElement('select'); source.className = 'field-directory-source'; source.replaceChildren(); const placeholder = document.createElement('option'); placeholder.value = ''; placeholder.textContent = 'Выберите справочник'; source.append(placeholder, ...directories.filter((directory) => directory.id !== draft.id).map((directory) => { const option = document.createElement('option'); option.value = directory.name; option.textContent = directory.name; return option; })); source.value = field.directory ?? ''; source.onchange = () => changeField(field.id, { directory: source.value }); if (!currentReference) row.insertBefore(source, controls); }); }, [mode, draft, directories]);
  const save = async (event) => { event.preventDefault(); const name = draft.name.trim(); if (!name || draft.fields.some((field) => !field.name.trim())) { setNotice('Заполните название справочника и всех полей.'); return; } if (directories.some((item) => item.id !== draft.id && item.name.toLowerCase() === name.toLowerCase())) { setNotice('Справочник с таким названием уже существует.'); return; } const result = { ...draft, name, fields: draft.fields.map((field) => field.id === 'code' ? { ...field, name: 'Код', type: 'числовой' } : { ...field, name: field.name.trim() }) }; if (mode === 'new') await onCreateDirectory(result); else await onUpdateDirectory(result); setSelectedId(result.id); setMode(null); setNotice('Справочник сохранён.'); };
  const remove = async () => { if (selected.name === 'Подразделения' && users.some((user) => user.department)) { setNotice('Нельзя удалить «Подразделения»: он связан с пользователями.'); setMode(null); return; } await onDeleteDirectory(selected.id); setSelectedId(null); setMode(null); setNotice('Справочник удалён.'); };
  return <section className="existing-directories-card"><div className="existing-directories-heading"><div><h2>Существующие справочники</h2><p>Код — обязательное числовое поле и присваивается автоматически.</p></div><div className="directory-actions-toolbar"><button className="primary-button" onClick={() => begin('new')}>Новый</button><button className="secondary-button" disabled={!selected} onClick={() => begin('edit')}>Редактировать</button><button className="directory-delete-button" disabled={!selected} onClick={() => begin('delete')}>Удалить</button></div></div><table><thead><tr><th>Справочник</th><th>Записей</th><th>Полей</th></tr></thead><tbody>{directories.map((item) => <tr key={item.id} className={item.id === selectedId ? 'selected' : ''} onClick={() => setSelectedId(item.id)} onDoubleClick={() => { setSelectedId(item.id); setDraft({ ...item, fields: normalizeFields(item) }); setMode('edit'); }}><td><strong>{item.name}</strong></td><td>{item.rows.length}</td><td>{normalizeFields(item).length}</td></tr>)}</tbody></table>{mode ? <div className="directory-window-backdrop"><section className="directory-action-window">{mode === 'delete' ? <><h2>Удаление справочника</h2><p>Удалить «{selected.name}» вместе со всеми записями?</p><div><button className="field-delete-button" onClick={remove}>Удалить</button><button className="secondary-button" onClick={() => setMode(null)}>Отмена</button></div></> : <form onSubmit={save}><h2>{mode === 'new' ? 'Новый справочник' : 'Редактирование справочника'}</h2><label>Наименование справочника<input autoFocus value={draft.name} onChange={(event) => setDraft((current) => ({ ...current, name: event.target.value }))}/></label><div className="schema-fields"><strong>Поля справочника</strong>{draft.fields.map((field) => <div className="schema-field-row" key={field.id}><input disabled={field.id === 'code'} value={field.id === 'code' ? 'Код' : field.name} onChange={(event) => changeField(field.id, { name: event.target.value })}/><select disabled={field.id === 'code'} value={field.id === 'code' ? 'числовой' : field.type} onChange={(event) => changeField(field.id, { type: event.target.value })}><option>текстовый</option><option>числовой</option><option>дата</option><option>телефон</option><option>файл</option></select></div>)}<button className="secondary-button add-field-inline" type="button" onClick={addField}>＋ Добавить поле</button></div><div><button className="primary-button" type="submit">Сохранить</button><button className="secondary-button" type="button" onClick={() => setMode(null)}>Отмена</button></div></form>}</section></div> : null}{notice ? <p className="user-message">{notice}</p> : null}</section>;
}

