  useEffect(() => { if (!mode) return; const input = [...document.querySelectorAll('.directory-action-window form input')].find((item) => item.value === draft?.department || item.closest('label')?.textContent?.startsWith('Подразделение')); if (!input) return; input.setAttribute('list', 'department-directory-list'); let list = document.getElementById('department-directory-list'); if (!list) { list = document.createElement('datalist'); list.id = 'department-directory-list'; document.body.appendChild(list); } list.replaceChildren(...departments.map((department) => { const option = document.createElement('option'); option.value = department; return option; })); return () => { if (list?.parentNode) list.remove(); }; }, [mode, departments, draft?.department]);
