  useEffect(() => { if (mode !== 'new') return; const nameInput = document.querySelector('.directory-action-window form input'); const handler = () => setDraft((current) => ({ ...current, name: nameInput.value, login: loginFromName(nameInput.value) })); nameInput?.addEventListener('input', handler); return () => nameInput?.removeEventListener('input', handler); }, [mode]);
  useEffect(() => { if (!mode) return; const inputs = document.querySelectorAll('.directory-action-window form input'); const nameInput = inputs[0]; const passwordInput = [...inputs].find((input) => input.type === 'password'); if (nameInput) { nameInput.setAttribute('list', 'employees-directory-list'); let list = document.getElementById('employees-directory-list'); if (!list) { list = document.createElement('datalist'); list.id = 'employees-directory-list'; document.body.appendChild(list); } list.replaceChildren(...employees.map((name) => { const option = document.createElement('option'); option.value = name; return option; })); } if (passwordInput) passwordInput.type = 'text'; return () => document.getElementById('employees-directory-list')?.remove(); }, [mode, employees]);
