function LegacyUsersAdminView({ users, currentUser, onCreateUser }) {
  const [name, setName] = useState('');
  const [login, setLogin] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('Исполнитель');
  const [message, setMessage] = useState('');
  const isAdmin = currentUser.role === 'Администратор';
  const submit = async (event) => {
    event.preventDefault();
    if (!isAdmin) return;
    if (users.some((user) => user.login?.toLowerCase() === login.trim().toLowerCase())) { setMessage('Этот логин уже используется.'); return; }
    if (!name.trim() || !login.trim() || !password) { setMessage('Заполните имя, логин и пароль.'); return; }
    const initials = name.trim().split(/\s+/).slice(0, 2).map((part) => part[0]).join('').toUpperCase();
    await onCreateUser({ id: `u${Date.now()}`, name: name.trim(), initials, role, login: login.trim(), password, color: '#4d72a8' });
    setName(''); setLogin(''); setPassword(''); setRole('Исполнитель'); setMessage('Пользователь создан. Он может войти по указанному логину и паролю.');
  };
  if (!isAdmin) return <main className="single-workspace"><div className="page-title-row"><div><h1>Пользователи и права</h1><p>Управление учётными записями доступно только администратору.</p></div></div></main>;
  return <main className="single-workspace users-admin"><div className="page-title-row"><div><h1>Пользователи и права</h1><p>Создавайте учётные записи и назначайте роли в иерархии доступа.</p></div></div><section className="user-admin-grid"><form className="user-create-card" onSubmit={submit}><h2>Новый пользователь</h2><label>ФИО<input value={name} onChange={(event) => setName(event.target.value)} placeholder="Например, Сидоров А. А."/></label><label>Логин<input value={login} onChange={(event) => setLogin(event.target.value)} placeholder="Например, sidorov" autoComplete="username"/></label><label>Пароль<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="Задайте пароль" autoComplete="new-password"/></label><label>Роль<select value={role} onChange={(event) => setRole(event.target.value)}><option>Администратор</option><option>Руководитель</option><option>Постановщик</option><option>Исполнитель</option><option>Наблюдатель</option></select></label><button className="primary-button" type="submit">Создать пользователя</button>{message ? <p className="user-message" role="status">{message}</p> : null}</form><section className="users-table-card"><h2>Созданные пользователи</h2><table><thead><tr><th>Пользователь</th><th>Логин</th><th>Роль</th><th>Доступ</th></tr></thead><tbody>{users.map((user) => <tr key={user.id}><td><span className="owner"><Avatar user={user} small/>{user.name}</span></td><td>{user.login}</td><td><span className="role-badge">{user.role}</span></td><td>{user.role === 'Администратор' ? 'Полный' : user.role === 'Руководитель' ? 'Управление задачами' : user.role === 'Постановщик' ? 'Свои задачи' : user.role === 'Исполнитель' ? 'Назначенные задачи' : 'Просмотр'}</td></tr>)}</tbody></table></section></section></main>;
}

function DirectoryAdministration({ directories, users, onCreateDirectory, onUpdateDirectory, onDeleteDirectory }) {
  const [selectedId, setSelectedId] = useState(directories[0]?.id ?? '');
  const [newName, setNewName] = useState('');
  const [fieldName, setFieldName] = useState('');
  const [fieldType, setFieldType] = useState('текстовый');
  const [notice, setNotice] = useState('');
  const selected = directories.find((directory) => directory.id === selectedId) ?? directories[0];
  const fields = selected?.fields?.length ? selected.fields : [{ id: 'code', name: 'Код', type: 'текстовый' }, { id: 'name', name: 'Наименование', type: 'текстовый' }, { id: 'owner', name: selected?.name === 'Контрагенты' ? 'Статус' : selected?.name === 'Роли и права' ? 'Права доступа' : 'Руководитель', type: 'текстовый' }];
  const createDirectory = async (event) => { event.preventDefault(); const name = newName.trim(); if (!name) { setNotice('Укажите наименование справочника.'); return; } if (directories.some((directory) => directory.name.toLowerCase() === name.toLowerCase())) { setNotice('Справочник с таким наименованием уже существует.'); return; } const directory = { id: `directory-${Date.now()}`, name, rows: [], fields: [{ id: 'code', name: 'Код', type: 'текстовый' }, { id: 'name', name: 'Наименование', type: 'текстовый' }] }; await onCreateDirectory(directory); setSelectedId(directory.id); setNewName(''); setNotice(`Справочник «${name}» создан.`); };
  const addField = async (event) => { event.preventDefault(); const name = fieldName.trim(); if (!selected || !name) { setNotice('Выберите справочник и укажите наименование поля.'); return; } if (fields.some((field) => field.name.toLowerCase() === name.toLowerCase())) { setNotice('Поле с таким наименованием уже есть.'); return; } const field = { id: `field-${Date.now()}`, name, type: fieldType }; await onUpdateDirectory({ ...selected, fields: [...fields, field] }); setFieldName(''); setFieldType('текстовый'); setNotice(`Поле «${name}» добавлено.`); };
  const deleteField = async (field) => { if (['code', 'name', 'owner'].includes(field.id)) { setNotice('Системное поле удалить нельзя.'); return; } if (!window.confirm(`Удалить поле «${field.name}»? Данные этого поля будут удалены из записей.`)) return; const nextRows = selected.rows.map((row) => { const { [field.id]: removed, ...rest } = row; return rest; }); await onUpdateDirectory({ ...selected, rows: nextRows, fields: fields.filter((item) => item.id !== field.id) }); setNotice(`Поле «${field.name}» удалено.`); };
  const deleteDirectory = async () => { if (!selected) return; if (selected.name === 'Подразделения' && users.some((user) => user.department)) { setNotice('Нельзя удалить «Подразделения»: справочник связан с пользователями.'); return; } if (!window.confirm(`Удалить справочник «${selected.name}» и все его записи?`)) return; await onDeleteDirectory(selected.id); setSelectedId(directories.find((directory) => directory.id !== selected.id)?.id ?? ''); setNotice(`Справочник «${selected.name}» удалён.`); };
  return <section className="directory-admin-card"><div className="directory-admin-heading"><div><h2>Настройка справочников</h2><p>Создавайте справочники и определяйте состав их реквизитов.</p></div><button className="directory-delete-button" disabled={!selected} onClick={deleteDirectory}>Удалить справочник</button></div><div className="directory-admin-grid"><form className="directory-admin-form" onSubmit={createDirectory}><h3>Новый справочник</h3><label>Наименование<input value={newName} onChange={(event) => setNewName(event.target.value)} placeholder="Например, Виды документов"/></label><button className="primary-button" type="submit">Создать справочник</button></form><form className="directory-admin-form" onSubmit={addField}><h3>Новое поле</h3><label>Справочник<select value={selected?.id ?? ''} onChange={(event) => setSelectedId(event.target.value)}>{directories.map((directory) => <option key={directory.id} value={directory.id}>{directory.name}</option>)}</select></label><label>Наименование поля<input value={fieldName} onChange={(event) => setFieldName(event.target.value)} placeholder="Например, Контактный телефон"/></label><label>Тип поля<select value={fieldType} onChange={(event) => setFieldType(event.target.value)}><option>текстовый</option><option>числовой</option><option>дата</option><option>телефон</option></select></label><button className="primary-button" type="submit">Добавить поле</button></form></div><div className="directory-fields-table"><div><h3>Поля: {selected?.name ?? '—'}</h3><span>Тип определяет формат ввода в справочнике.</span></div><table><thead><tr><th>№</th><th>Наименование</th><th>Тип</th><th/></tr></thead><tbody>{fields.map((field, index) => <tr key={field.id}><td>{index + 1}</td><td>{field.name}</td><td><span className="field-type-badge">{field.type}</span></td><td><button className="field-delete-button" disabled={['code', 'name', 'owner'].includes(field.id)} onClick={() => deleteField(field)}>Удалить</button></td></tr>)}</tbody></table></div>{notice ? <p className="user-message" role="status">{notice}</p> : null}</section>;
}

function ExistingDirectoriesList({ directories, users, onCreateDirectory, onUpdateDirectory, onDeleteDirectory }) {
  const [selectedId, setSelectedId] = useState(null);
  const [windowMode, setWindowMode] = useState(null);
  const [draft, setDraft] = useState(null);
  const [notice, setNotice] = useState('');
  const selected = directories.find((directory) => directory.id === selectedId);
  const defaultFields = (directory) => directory.fields?.length ? directory.fields : [{ id: 'code', name: 'Код', type: 'текстовый' }, { id: 'name', name: 'Наименование', type: 'текстовый' }, { id: 'owner', name: directory.name === 'Контрагенты' ? 'Статус' : directory.name === 'Роли и права' ? 'Права доступа' : 'Руководитель', type: 'текстовый' }];
  const openNew = () => { setDraft({ id: `directory-${Date.now()}`, name: '', rows: [], fields: [{ id: 'code', name: 'Код', type: 'текстовый' }, { id: 'name', name: 'Наименование', type: 'текстовый' }] }); setWindowMode('new'); };
  const openEdit = () => { if (!selected) { setNotice('Сначала выберите справочник в таблице.'); return; } setDraft({ ...selected, fields: defaultFields(selected) }); setWindowMode('edit'); };
  const openDelete = () => { if (!selected) { setNotice('Сначала выберите справочник в таблице.'); return; } setWindowMode('delete'); };
  const updateField = (fieldId, change) => setDraft((current) => ({ ...current, fields: current.fields.map((field) => field.id === fieldId ? { ...field, ...change } : field) }));
  const addField = () => setDraft((current) => ({ ...current, fields: [...current.fields, { id: `field-${Date.now()}`, name: '', type: 'текстовый' }] }));
  const save = async (event) => { event.preventDefault(); const name = draft.name.trim(); if (!name || draft.fields.some((field) => !field.name.trim())) { setNotice('Заполните наименование справочника и названия полей.'); return; } if (directories.some((directory) => directory.id !== draft.id && directory.name.toLowerCase() === name.toLowerCase())) { setNotice('Справочник с таким наименованием уже существует.'); return; } const result = { ...draft, name, fields: draft.fields.map((field) => ({ ...field, name: field.name.trim() })) }; if (windowMode === 'new') await onCreateDirectory(result); else await onUpdateDirectory(result); setSelectedId(result.id); setWindowMode(null); setNotice(windowMode === 'new' ? 'Справочник создан.' : 'Справочник сохранён.'); };
  const remove = async () => { if (!selected) return; if (selected.name === 'Подразделения' && users.some((user) => user.department)) { setNotice('Нельзя удалить «Подразделения»: справочник связан с пользователями.'); setWindowMode(null); return; } await onDeleteDirectory(selected.id); setSelectedId(null); setWindowMode(null); setNotice(`Справочник «${selected.name}» удалён.`); };
  return <section className="existing-directories-card"><div className="existing-directories-heading"><div><h2>Существующие справочники</h2><p>Выберите строку, затем воспользуйтесь нужным действием.</p></div><div className="directory-actions-toolbar"><button className="primary-button" onClick={openNew}>Новый</button><button className="secondary-button" disabled={!selected} onClick={openEdit}>Редактировать</button><button className="directory-delete-button" disabled={!selected} onClick={openDelete}>Удалить</button></div></div><table><thead><tr><th>Справочник</th><th>Записей</th><th>Полей</th></tr></thead><tbody>{directories.map((directory) => <tr key={directory.id} className={directory.id === selectedId ? 'selected' : ''} onClick={() => setSelectedId(directory.id)}><td><strong>{directory.name}</strong></td><td>{directory.rows.length}</td><td>{directory.fields?.length ?? 3}</td></tr>)}</tbody></table>{windowMode ? <div className="directory-window-backdrop" role="dialog" aria-modal="true"><section className="directory-action-window">{windowMode === 'delete' ? <><h2>Удаление справочника</h2><p>Удалить справочник «{selected?.name}» вместе со всеми его записями?</p><div><button className="field-delete-button" onClick={remove}>Удалить</button><button className="secondary-button" onClick={() => setWindowMode(null)}>Отмена</button></div></> : <form onSubmit={save}><h2>{windowMode === 'new' ? 'Новый справочник' : 'Редактирование справочника'}</h2><label>Наименование справочника<input autoFocus value={draft.name} onChange={(event) => setDraft((current) => ({ ...current, name: event.target.value }))}/></label><div className="schema-fields"><strong>Поля справочника</strong>{draft.fields.map((field) => <div className="schema-field-row" key={field.id}><input value={field.name} onChange={(event) => updateField(field.id, { name: event.target.value })} placeholder="Наименование поля"/><select value={field.type} onChange={(event) => updateField(field.id, { type: event.target.value })}><option>текстовый</option><option>числовой</option><option>дата</option><option>телефон</option></select></div>)}<button className="secondary-button add-field-inline" type="button" onClick={addField}>＋ Добавить поле</button></div><div><button className="primary-button" type="submit">Сохранить</button><button className="secondary-button" type="button" onClick={() => setWindowMode(null)}>Отмена</button></div></form>}</section></div> : null}{notice ? <p className="user-message" role="status">{notice}</p> : null}</section>;
}

function UsersAdminView({ users, directories, currentUser, onCreateUser, onUpdateUser, onCreateDirectory, onUpdateDirectory, onDeleteDirectory }) {
  const [name, setName] = useState('');
  const [department, setDepartment] = useState('');
  const [login, setLogin] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('Исполнитель');
  const [message, setMessage] = useState('');
  const [editingUser, setEditingUser] = useState(null);
  const isAdmin = currentUser.role === 'Администратор';
  const departments = (directories.find((directory) => directory.name === 'Подразделения')?.rows ?? []).map((row) => row.name);
  const submit = async (event) => {
    event.preventDefault();
    if (!name.trim() || !department.trim() || !login.trim() || !password) { setMessage('Заполните ФИО, подразделение, логин и пароль.'); return; }
    if (users.some((user) => user.login?.toLowerCase() === login.trim().toLowerCase())) { setMessage('Этот логин уже используется.'); return; }
    const initials = name.trim().split(/\s+/).slice(0, 2).map((part) => part[0]).join('').toUpperCase();
    await onCreateUser({ id: `u${Date.now()}`, name: name.trim(), initials, department: department.trim(), role, login: login.trim(), password, color: '#4d72a8' });
    setName(''); setDepartment(''); setLogin(''); setPassword(''); setRole('Исполнитель'); setMessage('Пользователь создан. Он может войти по указанному логину и паролю.');
  };
  const accessLabel = (userRole) => userRole === 'Администратор' ? 'Полный' : userRole === 'Руководитель' ? 'Управление задачами' : userRole === 'Постановщик' ? 'Свои задачи' : userRole === 'Исполнитель' ? 'Назначенные задачи' : 'Просмотр';
  const beginEdit = (user) => setEditingUser({ ...user, password: '' });
  const saveEdit = async (event) => { event.preventDefault(); if (!editingUser.name.trim() || !editingUser.department.trim() || !editingUser.login.trim()) { setMessage('Заполните ФИО, подразделение и логин.'); return; } const duplicate = users.find((user) => user.id !== editingUser.id && user.login?.toLowerCase() === editingUser.login.trim().toLowerCase()); if (duplicate) { setMessage('Этот логин уже используется.'); return; } const initials = editingUser.name.trim().split(/\s+/).slice(0, 2).map((part) => part[0]).join('').toUpperCase(); const original = users.find((user) => user.id === editingUser.id); await onUpdateUser({ ...original, ...editingUser, name: editingUser.name.trim(), department: editingUser.department.trim(), login: editingUser.login.trim(), initials, password: editingUser.password || original.password }); setEditingUser(null); setMessage('Данные пользователя сохранены.'); };
  if (!isAdmin) return <main className="single-workspace"><div className="page-title-row"><div><h1>Пользователи и права</h1><p>Управление учётными записями доступно только администратору.</p></div></div></main>;
  return <main className="single-workspace users-admin"><div className="page-title-row"><div><h1>Администрирование</h1><p>Пользователи, права доступа и настройка справочников.</p></div></div><DirectoryAdministration directories={directories} users={users} onCreateDirectory={onCreateDirectory} onUpdateDirectory={onUpdateDirectory} onDeleteDirectory={onDeleteDirectory}/><section className="user-admin-grid"><form className="user-create-card" onSubmit={submit}><h2>Новый пользователь</h2><label>ФИО<input value={name} onChange={(event) => setName(event.target.value)} placeholder="Например, Сидоров А. А."/></label><label>Подразделение<select value={department} onChange={(event) => setDepartment(event.target.value)}><option value="">Выберите подразделение</option>{departments.map((item) => <option key={item}>{item}</option>)}</select></label><label>Логин<input value={login} onChange={(event) => setLogin(event.target.value)} placeholder="Например, sidorov" autoComplete="username"/></label><label>Пароль<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="Задайте пароль" autoComplete="new-password"/></label><label>Роль<select value={role} onChange={(event) => setRole(event.target.value)}><option>Администратор</option><option>Руководитель</option><option>Постановщик</option><option>Исполнитель</option><option>Наблюдатель</option></select></label><button className="primary-button" type="submit">Создать пользователя</button>{message ? <p className="user-message" role="status">{message}</p> : null}</form><section className="users-table-card"><h2>Пользователи</h2>{editingUser ? <form className="user-edit-card" onSubmit={saveEdit}><div><h3>Редактирование: {editingUser.name}</h3><p>Подразделение выбирается из справочника. Оставьте пароль пустым, если его не нужно менять.</p></div><label>ФИО<input value={editingUser.name} onChange={(event) => setEditingUser((current) => ({ ...current, name: event.target.value }))}/></label><label>Подразделение<select value={editingUser.department || ''} onChange={(event) => setEditingUser((current) => ({ ...current, department: event.target.value }))}><option value="">Выберите подразделение</option>{departments.map((item) => <option key={item}>{item}</option>)}</select></label><label>Логин<input value={editingUser.login} onChange={(event) => setEditingUser((current) => ({ ...current, login: event.target.value }))}/></label><label>Новый пароль<input type="password" value={editingUser.password} onChange={(event) => setEditingUser((current) => ({ ...current, password: event.target.value }))} placeholder="Не менять" autoComplete="new-password"/></label><label>Роль<select value={editingUser.role} onChange={(event) => setEditingUser((current) => ({ ...current, role: event.target.value }))}><option>Администратор</option><option>Руководитель</option><option>Постановщик</option><option>Исполнитель</option><option>Наблюдатель</option></select></label><div className="user-edit-actions"><button className="primary-button" type="submit">Сохранить</button><button className="secondary-button" type="button" onClick={() => setEditingUser(null)}>Отмена</button></div></form> : null}<table><thead><tr><th>Пользователь</th><th>Подразделение</th><th>Логин</th><th>Роль</th><th>Доступ</th><th/></tr></thead><tbody>{users.map((user) => <tr key={user.id}><td><span className="owner"><Avatar user={user} small/>{user.name}</span></td><td>{user.department || 'Не указано'}</td><td>{user.login}</td><td><span className="role-badge">{user.role}</span></td><td>{accessLabel(user.role)}</td><td><button className="user-edit-button" onClick={() => beginEdit(user)}>Редактировать</button></td></tr>)}</tbody></table></section></section></main>;
}

function ReportsView({ directories }) {
  const [directoryId, setDirectoryId] = useState(() => directories[0]?.id ?? '');
  const selectedDirectory = directories.find((directory) => directory.id === directoryId) ?? directories[0];
  const fields = selectedDirectory?.fields?.length ? selectedDirectory.fields : [{ id: 'code', name: 'Код' }, { id: 'name', name: 'Наименование' }, { id: 'owner', name: 'Реквизит' }];
  const [selectedFieldIds, setSelectedFieldIds] = useState(() => fields.map((field) => field.id));
  const [notice, setNotice] = useState('');
  useEffect(() => { setSelectedFieldIds(fields.map((field) => field.id)); setNotice(''); }, [selectedDirectory?.id]);
  const selectedFields = fields.filter((field) => selectedFieldIds.includes(field.id));
  const rows = selectedDirectory?.rows ?? [];
  const value = (row, field) => { const cell = row[field.id]; return cell === undefined || cell === '' ? '—' : typeof cell === 'object' ? cell.name ?? 'Файл' : cell; };
  const toggleField = (fieldId) => setSelectedFieldIds((current) => current.includes(fieldId) ? current.filter((item) => item !== fieldId) : [...current, fieldId]);
  const exportReport = async (format) => {
    if (!selectedFields.length) { setNotice('Выберите хотя бы одно поле для отчёта.'); return; }
    const reportName = `Отчёт по справочнику «${selectedDirectory.name}»`;
    const table = `<table><thead><tr>${selectedFields.map((field) => `<th>${escapeExportValue(field.name)}</th>`).join('')}</tr></thead><tbody>${rows.map((row) => `<tr>${selectedFields.map((field) => `<td>${escapeExportValue(value(row, field))}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
    const generatedDate = new Intl.DateTimeFormat('ru-RU').format(new Date());
    const documentContent = `<html><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif}h1{font-size:18pt}p{color:#555}table{border-collapse:collapse;width:100%}th,td{border:1px solid #789;padding:6px;text-align:left}th{background:#eaf3ff}</style></head><body><h1>${escapeExportValue(reportName)}</h1><p>Дата формирования: ${generatedDate}</p>${table}</body></html>`;
    const safeName = selectedDirectory.name.replace(/[^а-яёa-z0-9_-]/gi, '_');
    if (format === 'excel') {
      const XLSX = await import('xlsx');
      const worksheet = XLSX.utils.aoa_to_sheet([[reportName], [`Дата формирования: ${generatedDate}`], selectedFields.map((field) => field.name), ...rows.map((row) => selectedFields.map((field) => value(row, field)))]);
      worksheet['!merges'] = selectedFields.length > 1 ? [{ s: { r: 0, c: 0 }, e: { r: 0, c: selectedFields.length - 1 } }, { s: { r: 1, c: 0 }, e: { r: 1, c: selectedFields.length - 1 } }] : [];
      worksheet['!cols'] = selectedFields.map((field) => ({ wch: Math.max(14, Math.min(42, field.name.length + 8)) }));
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, 'Отчёт');
      XLSX.writeFile(workbook, `Отчёт_${safeName}.xlsx`, { compression: true });
    } else downloadExport(documentContent, `Отчёт_${safeName}.doc`, 'application/msword;charset=utf-8');
    setNotice(format === 'excel' ? 'Отчёт выгружен в Excel.' : 'Отчёт выгружен в Word.');
  };
  return <main className="single-workspace reports-workspace"><div className="page-title-row"><div><h1>Отчёты</h1><p>Сформируйте выгрузку по данным справочника.</p></div></div><section className="report-builder"><div className="report-settings"><h2>Отчёт по справочнику</h2><label>Справочник<select value={selectedDirectory?.id ?? ''} onChange={(event) => setDirectoryId(event.target.value)}>{directories.map((directory) => <option key={directory.id} value={directory.id}>{directory.name}</option>)}</select></label><div className="report-field-heading"><strong>Поля отчёта</strong><button type="button" onClick={() => setSelectedFieldIds(selectedFieldIds.length === fields.length ? [] : fields.map((field) => field.id))}>{selectedFieldIds.length === fields.length ? 'Снять все' : 'Выбрать все'}</button></div><div className="report-fields">{fields.map((field) => <label key={field.id}><input type="checkbox" checked={selectedFieldIds.includes(field.id)} onChange={() => toggleField(field.id)}/><span>{field.name}</span><small>{field.type ?? 'текстовый'}</small></label>)}</div><div className="report-actions"><button className="primary-button" type="button" onClick={() => exportReport('excel')}>Выгрузить в Excel</button><button className="secondary-button" type="button" onClick={() => exportReport('word')}>Выгрузить в Word</button></div>{notice ? <p className="report-notice" role="status">{notice}</p> : null}</div><div className="report-preview"><div><h2>Предпросмотр</h2><span>{rows.length} строк</span></div>{selectedFields.length ? <div className="report-preview-table"><table><thead><tr>{selectedFields.map((field) => <th key={field.id}>{field.name}</th>)}</tr></thead><tbody>{rows.slice(0, 8).map((row, index) => <tr key={`${row.code ?? index}`} >{selectedFields.map((field) => <td key={field.id}>{value(row, field)}</td>)}</tr>)}</tbody></table></div> : <p className="report-empty">Выберите поля, которые должны войти в отчёт.</p>}{rows.length > 8 ? <small>Показаны первые 8 строк из {rows.length}.</small> : null}</div></section></main>;
}

function Placeholder({ section }) { const labels = { overview: ['Обзор', 'Сводная информация о работе организации'], admin: ['Администрирование', 'Настройка пользователей, ролей и параметров системы'] }; const [title, description] = labels[section]; return <main className="single-workspace"><div className="page-title-row"><div><h1>{title}</h1><p>{description}</p></div></div><section className="coming-soon"><div className="coming-icon">◌</div><h2>Раздел готов к настройке</h2><p>Основные рабочие модули доступны в разделе «Задачи», «Справочники» и «Документы».</p><button className="primary-button">Перейти к задачам</button></section></main>; }

function OrganizationSettings({ organization, currentUser, onSave }) {
  const [draft, setDraft] = useState(() => ({ ...organization }));
  const [notice, setNotice] = useState('');
  useEffect(() => setDraft({ ...organization }), [organization]);
  const change = (field) => (event) => setDraft((current) => ({ ...current, [field]: event.target.value }));
  const submit = async (event) => {
    event.preventDefault();
    const inn = draft.inn.replace(/\D/g, '');
    if (inn && ![10, 12].includes(inn.length)) { setNotice('ИНН должен содержать 10 или 12 цифр.'); return; }
    await onSave({ ...draft, inn, kpp: draft.kpp.replace(/\D/g, ''), ogrn: draft.ogrn.replace(/\D/g, ''), bik: draft.bik.replace(/\D/g, ''), correspondentAccount: draft.correspondentAccount.replace(/\D/g, ''), settlementAccount: draft.settlementAccount.replace(/\D/g, '') });
    setNotice('Реквизиты организации сохранены.');
  };
  if (currentUser.role !== 'Администратор') return <main className="single-workspace"><div className="page-title-row"><div><h1>Организация</h1><p>Просмотр и изменение реквизитов доступны администратору.</p></div></div></main>;
  return <main className="single-workspace organization-workspace"><div className="page-title-row"><div><h1>Организация</h1><p>Основные сведения, контакты и банковские реквизиты юридического лица.</p></div></div><form className="organization-form" onSubmit={submit}><section><h2>Основные сведения</h2><div className="organization-grid"><label className="wide-field">Полное наименование<input value={draft.legalName} onChange={change('legalName')} placeholder="Например, ООО «Вектор»"/></label><label>Сокращённое наименование<input value={draft.shortName} onChange={change('shortName')} placeholder="ООО «Вектор»"/></label><label>Руководитель<input value={draft.director} onChange={change('director')} placeholder="Фамилия Имя Отчество"/></label><label>ИНН<input value={draft.inn} onChange={change('inn')} inputMode="numeric" maxLength="12" placeholder="10 или 12 цифр"/></label><label>КПП<input value={draft.kpp} onChange={change('kpp')} inputMode="numeric" maxLength="9" placeholder="9 цифр"/></label><label>ОГРН / ОГРНИП<input value={draft.ogrn} onChange={change('ogrn')} inputMode="numeric" maxLength="15" placeholder="13 или 15 цифр"/></label></div></section><section><h2>Адреса и контакты</h2><div className="organization-grid"><label className="wide-field">Юридический адрес<input value={draft.legalAddress} onChange={change('legalAddress')} placeholder="Индекс, город, улица, дом"/></label><label className="wide-field">Почтовый адрес<input value={draft.postalAddress} onChange={change('postalAddress')} placeholder="Если отличается от юридического"/></label><label>Телефон<input value={draft.phone} onChange={change('phone')} type="tel" placeholder="+7 (000) 000-00-00"/></label><label>Электронная почта<input value={draft.email} onChange={change('email')} type="email" placeholder="info@example.ru"/></label><label>Сайт<input value={draft.website} onChange={change('website')} placeholder="https://example.ru"/></label></div></section><section><h2>Банковские реквизиты</h2><div className="organization-grid"><label className="wide-field">Наименование банка<input value={draft.bankName} onChange={change('bankName')} placeholder="Наименование обслуживающего банка"/></label><label>БИК<input value={draft.bik} onChange={change('bik')} inputMode="numeric" maxLength="9" placeholder="9 цифр"/></label><label>Корреспондентский счёт<input value={draft.correspondentAccount} onChange={change('correspondentAccount')} inputMode="numeric" maxLength="20" placeholder="20 цифр"/></label><label className="wide-field">Расчётный счёт<input value={draft.settlementAccount} onChange={change('settlementAccount')} inputMode="numeric" maxLength="20" placeholder="20 цифр"/></label></div></section><div className="organization-actions"><button className="primary-button" type="submit">Сохранить реквизиты</button>{notice ? <p role="status">{notice}</p> : null}</div></form></main>;
}

function ChatView({ users, messages, currentUser, onSendMessage }) {
  const contacts = useMemo(() => users.filter((candidate) => candidate.id !== currentUser.id), [users, currentUser.id]);
  const [selectedId, setSelectedId] = useState(() => contacts[0]?.id ?? '');
  const [text, setText] = useState('');
  useEffect(() => { if (!contacts.some((contact) => contact.id === selectedId)) setSelectedId(contacts[0]?.id ?? ''); }, [contacts, selectedId]);
  const selected = contacts.find((contact) => contact.id === selectedId);
  const conversation = useMemo(() => messages.filter((message) => (message.senderId === currentUser.id && message.recipientId === selectedId) || (message.senderId === selectedId && message.recipientId === currentUser.id)).toSorted((left, right) => left.createdAt.localeCompare(right.createdAt)), [messages, currentUser.id, selectedId]);
  const send = async (event) => { event.preventDefault(); const body = text.trim(); if (!body || !selectedId) return; await onSendMessage({ id: `m${Date.now()}${Math.random().toString(16).slice(2)}`, senderId: currentUser.id, recipientId: selectedId, text: body, createdAt: new Date().toISOString() }); setText(''); };
  const preview = (contact) => messages.filter((message) => (message.senderId === currentUser.id && message.recipientId === contact.id) || (message.senderId === contact.id && message.recipientId === currentUser.id)).toSorted((left, right) => right.createdAt.localeCompare(left.createdAt))[0];
  if (!contacts.length) return <main className="single-workspace"><div className="page-title-row"><div><h1>Чат</h1><p>Для начала работы добавьте в системе ещё одного пользователя.</p></div></div></main>;
  return <main className="single-workspace chat-workspace"><div className="page-title-row"><div><h1>Чат</h1><p>Личные сообщения между пользователями системы.</p></div></div><section className="chat-layout"><aside className="chat-contacts"><h2>Пользователи</h2>{contacts.map((contact) => { const lastMessage = preview(contact); return <button key={contact.id} className={contact.id === selectedId ? 'chat-contact active' : 'chat-contact'} onClick={() => setSelectedId(contact.id)}><Avatar user={contact}/><span><strong>{contact.name}</strong><small>{lastMessage ? lastMessage.text : contact.department || 'Нет сообщений'}</small></span></button>; })}</aside><section className="chat-dialog">{selected ? <><header><Avatar user={selected}/><div><h2>{selected.name}</h2><p>{selected.department || selected.role}</p></div></header><div className="chat-messages">{conversation.length ? conversation.map((message) => <div key={message.id} className={message.senderId === currentUser.id ? 'chat-message own' : 'chat-message'}><p>{message.text}</p><time>{new Intl.DateTimeFormat('ru-RU', { hour: '2-digit', minute: '2-digit' }).format(new Date(message.createdAt))}</time></div>) : <div className="chat-empty">Начните переписку с {selected.name}.</div>}</div><form className="chat-compose" onSubmit={send}><input value={text} onChange={(event) => setText(event.target.value)} placeholder="Введите сообщение" aria-label="Сообщение" maxLength="2000"/><button className="primary-button" type="submit" disabled={!text.trim()}>Отправить</button></form></> : null}</section></section></main>;
}

function App() {
  const [data, setData] = useState(null);
  const [user, setUser] = useState(null);
  const [section, setSection] = useState('tasks');
  const [query, setQuery] = useState('');
  const [focusedTaskId, setFocusedTaskId] = useState(null);
  useEffect(() => { loadDatabase().then(setData); }, []);
  const updateTask = (taskId, change) => {
    setData((current) => {
      const previousTask = current.tasks.find((item) => item.id === taskId);
      if (!previousTask) return current;
      const updatedTask = typeof change === 'function' ? change(previousTask) : change;
      const notifications = taskAssignmentMessages(updatedTask, previousTask.performerIds ?? []);
      void Promise.all([saveEntity('tasks', updatedTask), ...notifications.map((message) => saveEntity('messages', message))]);
      return { ...current, tasks: current.tasks.map((item) => item.id === updatedTask.id ? updatedTask : item), messages: [...current.messages, ...notifications] };
    });
  };
  const deleteTask = async (taskId) => {
    const task = data.tasks.find((item) => item.id === taskId);
    if (!task || !canManageTask(user, task)) return;
    await deleteEntity('tasks', taskId);
    setData((current) => ({ ...current, tasks: current.tasks.filter((task) => task.id !== taskId) }));
    setFocusedTaskId(null);
  };
  const addTask = async (draft) => { if (!canCreateTask(user)) return; const task = { id: `t${Date.now()}`, number: nextTaskNumber(data.tasks), title: draft.title.trim(), status: 'В работе', priority: 'Обычный', ownerId: user.id, dueDate: new Date().toISOString().slice(0, 10), dueTime: '18:00', description: '', progress: 0, documents: [], performerIds: [], attachments: [], completedPerformerIds: [], ...draft }; const notifications = taskAssignmentMessages(task); await Promise.all([saveEntity('tasks', task), ...notifications.map((message) => saveEntity('messages', message))]); setData((current) => ({ ...current, tasks: [task, ...current.tasks], messages: [...current.messages, ...notifications] })); setFocusedTaskId(task.id); setSection('tasks'); };
  const copyTask = async (sourceTask) => { const task = { ...sourceTask, id: `t${Date.now()}`, number: nextTaskNumber(data.tasks), title: `${sourceTask.title} — копия`, status: 'В работе', progress: 0, attachments: [], completedPerformerIds: [] }; const notifications = taskAssignmentMessages(task); await Promise.all([saveEntity('tasks', task), ...notifications.map((message) => saveEntity('messages', message))]); setData((current) => ({ ...current, tasks: [task, ...current.tasks], messages: [...current.messages, ...notifications] })); setFocusedTaskId(task.id); };
  const createUser = async (newUser) => { if (user.role !== 'Администратор') return; await saveEntity('users', newUser); setData((current) => ({ ...current, users: [...current.users, newUser] })); };
  const updateUser = async (updatedUser) => { if (user.role !== 'Администратор') return; await saveEntity('users', updatedUser); setData((current) => ({ ...current, users: current.users.map((item) => item.id === updatedUser.id ? updatedUser : item) })); if (user.id === updatedUser.id) setUser(updatedUser); };
  const deleteUser = async (userId) => { if (user.role !== 'Администратор' || user.id === userId) return; await deleteEntity('users', userId); setData((current) => ({ ...current, users: current.users.filter((item) => item.id !== userId) })); };
  const saveDirectoryRows = async (directoryId, rows) => { const directory = data.directories.find((item) => item.id === directoryId); if (!directory) return; const updated = { ...directory, rows }; await saveEntity('directories', updated); setData((current) => ({ ...current, directories: current.directories.map((item) => item.id === directoryId ? updated : item) })); };
  const createDirectory = async (directory) => { if (user.role !== 'Администратор') return; await saveEntity('directories', directory); setData((current) => ({ ...current, directories: [...current.directories, directory] })); };
  const updateDirectory = async (directory) => { if (user.role !== 'Администратор') return; await saveEntity('directories', directory); setData((current) => ({ ...current, directories: current.directories.map((item) => item.id === directory.id ? directory : item) })); };
  const deleteDirectory = async (directoryId) => { if (user.role !== 'Администратор') return; await deleteEntity('directories', directoryId); setData((current) => ({ ...current, directories: current.directories.filter((item) => item.id !== directoryId) })); };
  const saveOrganization = async (organization) => { if (user.role !== 'Администратор') return; await saveEntity('meta', organization); setData((current) => ({ ...current, organization })); };
  const addDocument = async (document) => { await saveEntity('documents', document); setData((current) => ({ ...current, documents: [document, ...current.documents] })); };
  const updateDocument = async (document) => { await saveEntity('documents', document); setData((current) => ({ ...current, documents: current.documents.map((item) => item.id === document.id ? document : item) })); };
  const deleteDocument = async (documentId) => { await deleteEntity('documents', documentId); setData((current) => ({ ...current, documents: current.documents.filter((item) => item.id !== documentId) })); };
  const sendMessage = async (message) => { await saveEntity('messages', message); setData((current) => ({ ...current, messages: [...current.messages, message] })); };
  if (!data) return <div className="loading-screen"><div className="loader"/>Загружаем рабочее пространство…</div>;
  if (!user) return <Login users={data.users} onLogin={setUser}/>;
  let content = <Placeholder section={section}/>;
  if (section === 'tasks') content = <TasksView tasks={data.tasks} users={data.users} documents={data.documents} currentUser={user} query={query} focusedTaskId={focusedTaskId} onAddTask={addTask} onCopyTask={copyTask} onUpdateTask={updateTask} onDeleteTask={deleteTask}/>;
  if (section === 'chat') content = <ChatView users={data.users} messages={data.messages} currentUser={user} onSendMessage={sendMessage}/>;
  if (section === 'directories') content = <DirectoriesMenuView directories={data.directories} onSaveDirectory={saveDirectoryRows}/>;
  if (section === 'documents-normative') content = <DocumentsView documents={data.documents} query={query} category="normative" currentUser={user} onAddDocument={addDocument} onUpdateDocument={updateDocument} onDeleteDocument={deleteDocument}/>;
  if (section === 'documents-internal') content = <DocumentsView documents={data.documents} query={query} category="internal" currentUser={user} onAddDocument={addDocument} onUpdateDocument={updateDocument} onDeleteDocument={deleteDocument}/>;
  if (section === 'reports') content = <ReportsView directories={data.directories}/>;
  if (section === 'settings-organization') content = <OrganizationSettings organization={data.organization} currentUser={user} onSave={saveOrganization}/>;
  if (section === 'settings-directories') content = <SettingsDirectoriesView directories={data.directories} users={data.users} currentUser={user} onCreateDirectory={createDirectory} onUpdateDirectory={updateDirectory} onDeleteDirectory={deleteDirectory}/>;
  if (section === 'settings-users') content = <UsersManagementFixed users={data.users} directories={data.directories} currentUser={user} onCreateUser={createUser} onUpdateUser={updateUser} onDeleteUser={deleteUser}/>;
  return <div className="app-shell"><Sidebar section={section} setSection={setSection} user={user}/><div className="app-main"><Topbar user={user} onLogout={() => setUser(null)} search={query} setSearch={setQuery}/>{content}</div></div>;
}

export default App;
